// Üretilen dosya: tool/ozgun/uret.py. Toplum ve Sosyal Bilimler · Sosyal psikoloji (orta).
const ozSocialscience10Orta = <(String, String, List<String>, String)>[
  ('Floyd Allport\'un 1924 tarihli \'Social Psychology\' kitabı alana hangi yönelimi kazandırmasıyla bilinir?', 'Deneysel yöntemi ve bireyin davranışını merkeze almayı', ['Kalabalıkların ortak ruhunu incelemeyi', 'Bilinçdışı çatışmaları açıklamayı', 'Toplumsal sınıfların çatışmasını tarihsel olarak çözümlemeyi'], 'Floyd Allport sosyal davranışı bireyin tepkileri üzerinden ve deneysel yöntemle incelemeyi savunmuş, \'grup zihni\' gibi kavramlara karşı çıkmıştır.'),
  ('Kurt Lewin\'e ait \'İyi bir kuram kadar pratik bir şey yoktur\' sözü sosyal psikoloji açısından neyi vurgular?', 'Kuramla toplumsal sorunlara uygulamanın birbirini beslemesini', ['Kuramların günlük yaşamın sorunlarında hiçbir işe yaramadığını', 'Deneylerin kuram olmadan yapılması gerektiğini', 'Yalnızca laboratuvar bulgularının geçerli olduğunu'], 'Lewin, sağlam kuramların toplumsal sorunları çözmede yol gösterdiğini ve uygulamanın da kuramı geliştirdiğini savunmuştur.'),
  ('Alan deneylerinin laboratuvar deneylerine göre en önemli üstünlüğü hangisidir?', 'Bulguların gerçek yaşama genellenebilirliğinin daha yüksek olması', ['Değişkenlerin tamamen denetlenebilmesi', 'Katılımcılardan bilgilendirilmiş onamın çok daha kolay alınabilmesi', 'Neden-sonuç ilişkisinin hiç kurulamaması'], 'Alan deneyleri doğal ortamda yapıldığından dış geçerliliği yüksektir; buna karşın değişkenlerin denetimi laboratuvara göre daha zordur.'),
  ('Sosyal psikolojide \'deneysel gerçekçilik\' kavramı neyi anlatır?', 'Deney durumunun katılımcıyı içine çekecek ve ciddiye aldıracak kadar etkileyici olmasını', ['Deney ortamının günlük yaşamdaki bir ortama dış görünüşçe benzemesini', 'Deneyin farklı ülkelerde tekrarlanabilmesini', 'Katılımcıların gerçek adlarıyla kaydedilmesini'], 'Deneysel gerçekçilik deneyin katılımcı için anlamlı ve inandırıcı olmasıdır; dış görünüşçe günlük yaşama benzerliğe ise dünyevi gerçekçilik denir.'),
  ('Birçok klasik sosyal psikoloji deneyinin katılımcılarının büyük bölümünün Batılı üniversite öğrencilerinden oluşması hangi eleştiriye yol açar?', 'Bulguların bütün insanlara genellenmesinin sorgulanabilir olması', ['Deneylerin iç geçerliliğinin tamamen ve kesin olarak ortadan kalkması', 'Öğrencilerin yönergeleri anlayamaması', 'Değişkenlerin hiç ölçülememesi'], 'Batılı, eğitimli ve sanayileşmiş toplumlardan seçilen örneklemler, bulguların farklı kültürlere ve yaş gruplarına genellenip genellenemeyeceği sorusunu doğurur.'),
  ('Bir araştırmacı, ülkelerin ortalama sıcaklıkları ile şiddet suçu oranları arasındaki ilişkiyi geçmiş yılların resmi kayıtlarından inceliyor. Bu araştırmadan hangi sonuç çıkarılamaz?', 'Sıcaklığın şiddete kesin olarak neden olduğu', ['İki değişken arasında bir ilişki olup olmadığı', 'İlişkinin yönünün olumlu ya da olumsuz olduğu', 'İlişkinin gücünün ne düzeyde olduğu'], 'Arşiv kayıtlarına dayalı ilişkisel araştırmalar değişkenler arasındaki ilişkiyi gösterir; ancak araya giren üçüncü değişkenler nedeniyle neden-sonuç kesinliği sağlamaz.'),
  ('Kendini öğrenci, kardeş, gitarist, gönüllü ve takım kaptanı gibi birbirinden ayrı birçok yönüyle tanımlayan bir kişinin, bu yönlerden birinde yaşadığı başarısızlıktan genel benlik değerinin daha az etkilenmesi hangi kavramla açıklanır?', 'Benlik karmaşıklığı', ['Benlik tutarlılığı', 'Benlik izleme', 'Benlik sunumu'], 'Patricia Linville\'in benlik karmaşıklığı kavramına göre benliği çok ve birbirinden bağımsız yönlerden oluşan kişiler, tek bir alandaki olumsuz olaydan daha az etkilenir.'),
  ('Bir amatör koşucunun kendini olimpiyat şampiyonuyla değil, kendi düzeyine yakın koşucularla karşılaştırmayı tercih etmesi Festinger\'in kuramındaki hangi önermeye uygundur?', 'İnsanlar kendilerine benzer kişilerle karşılaştırma yapmayı tercih eder', ['İnsanlar yalnızca en başarılı kişileri ölçüt alır', 'Karşılaştırma yalnızca grup içinde ve zorunlu olarak yapılır, isteğe bağlı değildir', 'İnsanlar karşılaştırmadan kaçınmayı her zaman seçer'], 'Festinger\'e göre en bilgilendirici karşılaştırma benzer yetenek ve görüşteki kişilerle yapılan karşılaştırmadır.'),
  ('Sosyal medyada başkalarının yalnızca en iyi anlarını gören gençlerde yaşam doyumunun düşmesi, sosyal karşılaştırma açısından nasıl yorumlanır?', 'Sürekli yukarıya doğru karşılaştırma yapılmasının öz değerlendirmeyi zedelemesi', ['Aşağıya doğru karşılaştırmanın öz saygıyı aşırı yükseltmesi', 'Karşılaştırma yapılamamasının kaygı yaratması', 'Benzer kişilerle karşılaştırmanın moral artırması'], 'Kendinden daha iyi görünen kişilerle sürekli kıyaslama, kişinin kendini yetersiz hissetmesine yol açabilir.'),
  ('Abraham Tesser\'in benlik değerlendirmesini koruma modeline göre yakın bir arkadaşın, kişinin kendisi için önemli olan bir alanda ondan daha başarılı olması hangi sonucu doğurur?', 'Kıyaslama nedeniyle kişinin öz değerlendirmesinin tehdit edilmesi', ['Arkadaşın başarısıyla övünülerek benliğin güçlenmesi ve gururun artması', 'Kişinin o alana ilgisinin kesin olarak artması', 'Arkadaşlığın kesinlikle güçlenmesi'], 'Tesser\'e göre başarı kişi için önemli bir alandaysa yakın birinin üstünlüğü karşılaştırma yoluyla öz değerlendirmeyi düşürür; önemsiz bir alandaysa yansıma yoluyla gurur verir.'),
  ('Tesser\'in modeline göre bir piyanistin, kendisi için önemli olmayan futbol alanında başarılı olan yakın arkadaşıyla gurur duyması hangi süreçle açıklanır?', 'Yansıma', ['Karşılaştırma', 'Bastırma', 'Koşullanma'], 'Başarı kişinin benliği için önemli olmayan bir alanda gerçekleştiğinde, yakın birinin başarısı yansıma yoluyla kişiye de gurur verir.'),
  ('Robert Cialdini\'nin üniversite öğrencileriyle yaptığı çalışmada, okul takımlarının kazandığı maçların ertesi günü kampüste okul adını taşıyan giysilerin daha çok giyildiği görülmüştür. Bu olguya ne ad verilir?', 'Yansıyan şöhretin tadını çıkarma', ['Grup düşüncesi', 'Sosyal kaytarma', 'Ait olmama yanılgısı'], 'Başarılı kişi ya da gruplarla ilişkilendirilerek benlik saygısını yükseltme eğilimi İngilizce adıyla BIRGing (yansıyan şöhretin tadını çıkarma) olarak bilinir.'),
  ('Mark Snyder\'ın kavramlaştırdığı \'kendini izleme\' özelliği yüksek olan kişilerin belirgin davranış eğilimi hangisidir?', 'Bulundukları ortama göre davranışlarını ustaca ayarlamaları', ['Her ortamda yalnızca iç duygularına göre ve hep aynı biçimde davranmaları', 'Başkalarının görüşlerine hiç dikkat etmemeleri', 'Sosyal ortamlardan sürekli kaçınmaları'], 'Kendini izleme düzeyi yüksek kişiler sosyal ipuçlarına duyarlıdır ve izlenim yaratmak için davranışlarını duruma göre değiştirir; düşük olanlar iç tutumlarına göre davranır.'),
  ('Kendini engelleme stratejisinin kişiye sağladığı kısa vadeli \'yarar\' hangisidir?', 'Başarısızlıkta yetenek algısının korunması, başarıda ise övgünün artması', ['Başarı olasılığının kesin olarak artması', 'Başkalarının kişiye daha çok güvenmesi', 'Görevin daha kolay hale gelmesi'], 'Engel varken başarısızlık engele, başarı ise engele rağmen elde edildiği için yeteneğe bağlanabilir; ancak uzun vadede başarıyı düşürür.'),
  ('Daryl Bem\'in öz algı kuramına göre insanlar kendi tutumlarını, özellikle iç durumları belirsiz olduğunda nasıl çıkarsar?', 'Kendi davranışlarını ve bu davranışın koşullarını gözlemleyerek', ['Yalnızca çocukluk anılarına bakarak', 'Başkalarının tutumlarını hiç düşünmeden doğrudan kopyalayarak', 'Bilinçdışı dürtülerini çözümleyerek'], 'Bem\'e göre kişi kendini bir dış gözlemci gibi izler ve \'Bunu yaptığıma göre bundan hoşlanıyor olmalıyım\' biçiminde çıkarım yapar.'),
  ('Aşırı gerekçelendirme araştırmalarına göre hangi tür ödül iç güdülenmeye en az zarar verir?', 'Beklenmedik biçimde verilen ve yetkinliği bildiren sözel övgü', ['Önceden vaat edilen ve görevi yapmaya bağlı para', 'Her denemede verilen somut armağan', 'Görevi bitirince sözleşmeyle verilen ödül'], 'Beklenmeyen ve başarıyı bildiren ödüller davranışın nedenini dışa yükletmeye yol açmadığı için iç güdülenmeyi koruyabilir.'),
  ('Düzenli bağış yapan birinin \'Benim gibi cömert insan çok azdır\' diye düşünmesi, olumlu özelliklerin ne kadar ender olduğunu abartma biçiminde hangi yanılgıdır?', 'Yanlış teklik etkisi', ['Yanlış uzlaşma etkisi', 'Temel atıf hatası', 'Kendini engelleme'], 'İnsanlar olumlu yetenek ve erdemlerinin başkalarında daha az bulunduğunu düşünme eğilimindedir; buna yanlış teklik etkisi denir.'),
  ('Duval ve Wicklund\'un nesnel öz farkındalık kuramına göre ayna karşısında ya da kamera tarafından kaydedilirken dikkatini kendine yönelten kişide ne olur?', 'Kendini kişisel standartlarıyla karşılaştırması artar', ['Kişisel standartları tamamen unutulur', 'Kimliksizleşme duygusu güçlenir', 'Dikkati yalnızca çevredeki nesnelere ve başkalarına yönelir'], 'Dikkatin benliğe yönelmesi kişinin davranışını ideal ve standartlarıyla karşılaştırmasına yol açar; bu da çoğu zaman standartlara uygun davranmayı artırır.'),
  ('Susan Fiske ve Shelley Taylor\'ın sosyal bilişte insanı \'bilişsel cimri\' olarak nitelemesi neyi anlatır?', 'İnsanların zihinsel çabadan kaçınıp kestirme yollarla yargıya varma eğilimini', ['İnsanların her bilgiyi titizlikle tarttığını', 'İnsanların para harcamaktan kaçındığını', 'İnsanların duygularını hiç göstermediğini'], 'Bilişsel cimri benzetmesi, sınırlı bilişsel kaynakları korumak için insanların sıklıkla basitleştirici kestirmelere başvurduğunu vurgular.'),
  ('Sosyal bilişte \'güdülenmiş taktisyen\' görüşü, \'bilişsel cimri\' görüşünden hangi yönüyle ayrılır?', 'Kişinin amacına ve önemine göre kestirme ya da dikkatli düşünme arasında seçim yapabilmesi', ['İnsanların her zaman kestirme yol kullanması', 'İnsanların hiçbir zaman hata yapmaması', 'Düşünmenin yalnızca duygularla yönlendirilmesi'], 'Güdülenmiş taktisyen yaklaşımına göre insanlar durumun önemine göre bazen hızlı ve otomatik, bazen yavaş ve dikkatli düşünme stratejilerini seçer.'),
  ('Medvec ve arkadaşlarının 1992 Olimpiyatları çekimleri üzerindeki çalışmasında bronz madalya kazananların gümüş madalya kazananlardan daha mutlu göründüğü bulunmuştur. Bunun en iyi açıklaması hangisidir?', 'Gümüş kazananların altını, bronz kazananların ise madalyasız kalmayı düşünmesi', ['Bronz madalyanın maddi değerinin daha yüksek olması', 'Gümüş kazananların daha yaşlı olması', 'Bronz kazananların daha az yorulması'], 'Karşı-olgusal düşüncede gümüş madalyacılar \'Az kalsın altın alıyordum\' diye yukarı doğru, bronz madalyacılar \'Az kalsın madalyasız kalıyordum\' diye aşağı doğru düşünür.'),
  ('Asch\'in bir deneyinde aynı altı özellik bir gruba \'zeki, çalışkan, dürtüsel, eleştirel, inatçı, kıskanç\', diğer gruba ters sırayla verilmiştir. İlk listeyi okuyanların kişi hakkında daha olumlu izlenim edinmesi hangi etkiyi gösterir?', 'Öncelik etkisi', ['Sonralık etkisi', 'Hale etkisi', 'Zıtlık etkisi'], 'Öncelik etkisi, izlenim oluşumunda ilk alınan bilgilerin sonraki bilgilere göre daha fazla ağırlık taşımasıdır.'),
  ('Fritz Heider\'in \'Kişilerarası İlişkilerin Psikolojisi\' (1958) adlı eserinde insanları bir tür \'saf bilim insanı\' olarak görmesi neyi anlatır?', 'Günlük yaşamda davranışların nedenlerini mantıklı biçimde açıklamaya çalışmalarını', ['Laboratuvarda deney yapmayı sevmelerini', 'Bilimsel bilgiyi her zaman doğru kullanmalarını', 'Yalnızca bilim insanlarının atıf yaptığını'], 'Heider\'e göre sıradan insanlar başkalarının davranışlarını anlamlandırmak için nedenleri içsel ya da dışsal etkenlere yükleyen \'naif psikologlar\'dır.'),
  ('Kelley\'in kovaryasyon modelinde \'uzlaşma\' (consensus) bilgisi hangi soruyu yanıtlar?', 'Başka insanlar da aynı uyarıcıya karşı benzer davranıyor mu?', ['Kişi bu uyarıcıya her zaman böyle mi davranıyor?', 'Kişi başka uyarıcılara ve başka durumlara da böyle mi davranıyor?', 'Kişi bu davranıştan pişman mı?'], 'Uzlaşma, aynı duruma başkalarının da aynı tepkiyi verip vermediğini gösterir; tutarlılık zaman içindeki, ayırt edicilik ise uyarıcılar arasındaki farkı inceler.'),
  ('Ali bir filmi çok beğenmiştir. Arkadaşlarının hiçbiri bu filmi beğenmemiştir, Ali hemen her filmi beğenir ve bu filmi her izleyişinde beğenmiştir. Kelley\'in modeline göre Ali\'nin beğenisi büyük olasılıkla neye yüklenir?', 'Ali\'nin kendi kişisel özelliklerine', ['Filmin üstün niteliklerine', 'O günkü özel koşullara', 'Arkadaşlarının yanlış ve önyargılı yargısına'], 'Düşük uzlaşma, düşük ayırt edicilik ve yüksek tutarlılık bir arada olduğunda davranış kişinin içsel özelliklerine yüklenir.'),
  ('Zeynep bir öğretmenden çok korkmaktadır. Sınıftaki herkes o öğretmenden korkar, Zeynep başka öğretmenlerden korkmaz ve bu öğretmenden her zaman korkmuştur. Kelley\'in modeline göre bu korku en çok neye yüklenir?', 'Öğretmenin kendisine', ['Zeynep\'in kaygılı ve ürkek kişiliğine', 'Tesadüfi bir güne', 'Zeynep\'in ailesine'], 'Yüksek uzlaşma, yüksek ayırt edicilik ve yüksek tutarlılık davranışın uyarıcıdan, yani dış etkenden kaynaklandığını düşündürür.'),
  ('Kelley\'in \'indirgeme ilkesi\'ne göre bir davranışın birden fazla olası nedeni olduğunda gözlemci ne yapar?', 'Herhangi bir nedenin rolünü daha az önemli görür', ['Bütün olası nedenlere eşit ve oldukça yüksek ağırlık verir', 'Davranışı açıklamaktan tamamen vazgeçer', 'Yalnızca en son nedeni dikkate alır'], 'Örneğin bir ünlünün bir ürünü övmesi, aldığı yüksek ücret de bilindiğinde, ürünü gerçekten beğendiği şeklindeki açıklamanın ağırlığını azaltır.'),
  ('Jones ve Davis\'in uyumlu çıkarım kuramına göre bir davranıştan kişinin gerçek özelliğine ilişkin en güçlü çıkarım hangi koşulda yapılır?', 'Davranış özgürce seçildiğinde ve sosyal olarak beklenmedik olduğunda', ['Davranış zorla yaptırıldığında', 'Davranış herkesin yapacağı türden olduğunda', 'Davranışın birçok ortak sonucu olduğunda'], 'Seçim özgürlüğü, beklenmedik oluş ve ayırt edici sonuçlar, davranışın kişinin gerçek eğilimini yansıttığı çıkarımını güçlendirir.'),
  ('Bernard Weiner\'in başarı ve başarısızlıkla ilgili atıf modelinde, sınavda başarısız olan bir öğrencinin bunu \'yeteneksizliğine\' bağlaması hangi boyut bileşimine karşılık gelir?', 'İçsel, kalıcı ve denetlenemez', ['Dışsal, değişken ve denetlenebilir', 'İçsel, değişken ve denetlenebilir', 'Dışsal, kalıcı ve denetlenemez'], 'Weiner\'e göre yetenek kişiye ait (içsel), zamanla kolay değişmeyen (kalıcı) ve kişinin isteğiyle hemen değiştiremeyeceği (denetlenemez) bir nedendir.'),
  ('Weiner\'in modeline göre başarısızlığını \'yeterince çalışmamaya\' bağlayan bir öğrencinin bir sonraki sınav için umudunun daha yüksek olması neden beklenir?', 'Çaba değişken ve denetlenebilir bir neden olduğu için', ['Çaba kalıcı, değişmez ve değiştirilemez olduğu için', 'Çaba dışsal bir neden olduğu için', 'Çaba şansa bağlı olduğu için'], 'Değişken ve denetlenebilir nedenlere yapılan atıflar, kişinin sonucu değiştirebileceğine inanmasını sağlar ve güdülenmeyi korur.'),
  ('Aktör-gözlemci farkının ortaya çıkmasında \'algısal belirginlik\' nasıl bir rol oynar?', 'Gözlemci kişiye, aktör ise çevreye baktığı için farklı etkenler göze çarpar', ['Aktör kendini aynada sürekli gördüğü için', 'Gözlemci durumu aktörden daha iyi bildiği için', 'İki taraf da aynı şeye baktığı için'], 'Davranışı yapan kişi dikkatini çevresine yönelttiğinden durumsal etkenleri, gözlemci ise aktörü izlediğinden kişisel etkenleri daha belirgin algılar.'),
  ('Melvin Lerner\'in \'adil dünya inancı\' kavramına göre bu inanca sahip kişilerin bir talihsizlik yaşayan biri hakkında sıklıkla ne düşünmesi beklenir?', 'Kişinin başına geleni bir biçimde hak ettiğini', ['Olayın tamamen şansa bağlı olduğunu', 'Toplumun kişiye borçlu olduğunu', 'Herkesin aynı talihsizliği bir gün yaşayabileceğini'], 'İnsanlar iyiye iyi, kötüye kötü şeyler olduğuna inanmak isteyebilir; bu da mağdurun suçlanmasına yol açabilir.'),
  ('Thomas Pettigrew\'in \'nihai atıf hatası\' kavramı neyi anlatır?', 'Dış grup üyelerinin olumsuz davranışlarını onların doğasına, olumlu davranışlarını ise şansa bağlama eğilimini', ['Kendi başarılarını şansa bağlama eğilimini', 'Herkesin davranışını durumla açıklamayı', 'İç grubun kusurlarını abartma eğilimini'], 'Nihai atıf hatası, temel atıf hatasının gruplar arası düzeye taşınmış biçimidir ve önyargıyı besler.'),
  ('Kültürler arası araştırmalar, temel atıf hatasının hangi tür toplumlarda daha zayıf görüldüğünü ortaya koymuştur?', 'Doğu Asya gibi toplulukçu kültürlerde', ['Kuzey Amerika gibi bireyci kültürlerde', 'Yalnızca sanayileşmiş Batı ülkelerinde', 'Kültürden bağımsız olarak her yerde aynı düzeyde'], 'Toplulukçu kültürlerde bireyler davranışı bağlam ve ilişkiler içinde düşündüğünden durumsal etkenleri daha çok hesaba katar.'),
  ('Kendini doğrulayan kehanetin gerçekleşmesi için hangi aşamaların sırayla oluşması gerekir?', 'Beklenti, beklentiye uygun davranış, karşı tarafın buna uyan tepkisi', ['Karşı tarafın tepkisi, beklenti, ödül', 'Ödül, ceza, beklenti', 'Gözlem, unutma, yeniden öğrenme'], 'Önce bir beklenti oluşur, kişi bu beklentiye göre davranır ve hedef kişi de bu davranışa beklentiyi doğrulayacak biçimde karşılık verir.'),
  ('Tek yumurta ve çift yumurta ikizleriyle yapılan araştırmalar, bazı tutumlar için hangi sonucu desteklemektedir?', 'Tutumların bir kısmının kalıtsal etkilerden de payı bulunabileceğini', ['Tutumların tamamen genetik olduğunu', 'Tutumların çevreden hiç etkilenmediğini', 'İkizlerin hiçbir tutumda benzeşmediğini'], 'İkiz araştırmaları bazı tutumlarda tek yumurta ikizlerinin daha fazla benzeştiğini göstermiş; ancak bu kalıtım etkisinin dolaylı olduğu, mizaç gibi özellikler üzerinden işlediği düşünülmektedir.'),
  ('Doğrudan deneyime dayanan tutumların, başkalarından duyulan bilgilere dayanan tutumlara göre davranışı daha iyi yordaması neyle açıklanır?', 'Daha güçlü, daha kolay erişilebilir ve daha kararlı olmalarıyla', ['Daha az bilgi içermeleriyle', 'Daha kolay unutulmalarıyla', 'Hiçbir duygusal bileşen taşımamaları ve tamamen nesnel olmalarıyla'], 'Kişisel deneyimden gelen tutumlar zihinde daha erişilebilirdir ve kesinlikle tutulur; bu nedenle davranışla daha tutarlıdır.'),
  ('Planlı davranış kuramındaki \'öznel norm\' kavramı neyi ifade eder?', 'Kişinin önemsediği başkalarının o davranışı onaylayıp onaylamadığına ilişkin algısını', ['Kişinin davranış hakkındaki kendi duygularını', 'Davranışın yasal olup olmadığını', 'Kişinin davranışı yapma becerisini'], 'Öznel norm, aile, arkadaş gibi önemli kişilerin beklentisine ilişkin algı ve bu beklentiye uyma isteğidir.'),
  ('Bir araştırmada \'çevreye karşı genel tutum\' ölçüldüğünde, belirli bir hafta sonu yapılacak geri dönüşüm kampanyasına katılımın zayıf yordandığı görülmüştür. Bu sonuç tutum-davranış ilişkisinde hangi ilkenin önemini gösterir?', 'Tutum ile davranışın aynı özgüllük düzeyinde ölçülmesi gerektiğini', ['Tutumların hiçbir zaman davranışı yordamadığını', 'Davranışın yalnızca kişiliğe bağlı olduğunu', 'Genel tutumların özel tutumlardan daha güçlü olduğunu'], 'Ajzen ve Fishbein\'in uygunluk ilkesine göre belirli bir davranışı yordamak için o davranışa özgü tutumun ölçülmesi gerekir.'),
  ('Bir kişinin bir konuya ilişkin tutumunun zihninde ne kadar hızlı ve kolay akla geldiğini anlatan tutum özelliği hangisidir?', 'Tutumun erişilebilirliği', ['Tutumun bilişsel karmaşıklığı', 'Tutumun yönü', 'Tutumun özgüllüğü'], 'Erişilebilirliği yüksek tutumlar otomatik olarak harekete geçer ve davranışı daha güçlü yönlendirir; genellikle tepki süresiyle ölçülür.'),
  ('Emory Bogardus\'un geliştirdiği ölçekte katılımcılara \'Bu gruptan biriyle evlenir miydiniz?\', \'Komşunuz olmasını ister miydiniz?\' gibi sorular sorulur. Bu ölçek neyi belirlemeye çalışır?', 'Kişilerin farklı gruplara ne ölçüde yakınlık kabul ettiğini', ['Kişilerin zekâ düzeyini', 'Kişilerin kişilik tiplerini ve mizaç özelliklerini', 'Grupların ekonomik gelirini'], 'Bogardus sosyal uzaklık ölçeği, farklı yakınlık düzeylerinde ilişkiyi kabul etme isteği üzerinden gruplar arası tutumları ölçer.'),
  ('Greenwald ve arkadaşlarının 1998\'de geliştirdiği Örtük İlişkilendirme Testi (IAT) tutumları neye dayanarak ölçer?', 'Kavram çiftlerini sınıflandırma sırasındaki tepki sürelerine', ['Katılımcının açık yanıtlarına', 'Kalp atışı, terleme ve kan basıncı ölçümlerine', 'Gözlemcilerin puanlamalarına'], 'IAT, iki kavramın zihinde ne kadar güçlü ilişkili olduğunu bilgisayarda yapılan sınıflandırmadaki hız farklarından çıkarır.'),
  ('Örtük tutum ölçümlerinin, kişiye doğrudan görüşünü soran anketlere göre en önemli avantajı hangisidir?', 'Sosyal beğenirlik kaygısından daha az etkilenmeleri', ['Uygulamalarının her zaman daha kolay olması', 'Kişinin bilinçli görüşünü her durumda kesin olarak göstermeleri', 'Hiçbir ölçme hatası içermemeleri'], 'İnsanlar açık ölçümlerde kendilerini olumlu göstermek isteyebilir; örtük ölçümler istemli denetimi zorlaştırarak bu etkiyi azaltır.'),
  ('Jones ve Sigall\'ın 1971\'de tanımladığı \'sahte veri hattı\' tekniğinde katılımcılara ne söylenir?', 'Bağlandıkları cihazın gerçek duygularını ortaya çıkaracağı', ['Yanıtlarının hiç kaydedilmeyeceği', 'Yanlış yanıt verenlerin ödüllendirileceği', 'Deneyin yalnızca zekâyı ölçtüğü'], 'Katılımcılar yalan söylendiğinde cihazın bunu anlayacağına inandırılır; böylece daha dürüst yanıt vermeleri sağlanır.'),
  ('Aronson ve Mills\'in 1959 deneyinde utandırıcı ve zor bir kabul sınavından geçerek sıkıcı bir tartışma grubuna katılan öğrenciler, grubu kolay sınavla girenlere göre nasıl değerlendirmiştir?', 'Daha ilginç ve değerli', ['Daha sıkıcı ve değersiz', 'Tamamen aynı', 'Katılmaya değmez'], 'Bir şey için çok çaba harcayan kişi, bu çabayı gerekçelendirmek için ulaştığı şeye daha fazla değer biçer; buna çaba gerekçelendirmesi denir.'),
  ('Aronson ve Carlsmith\'in 1963 \'yasak oyuncak\' deneyinde çocuklara en sevdikleri oyuncakla oynamamaları söylenmiştir. Hafif cezayla tehdit edilen çocuklar sonradan oyuncağı nasıl değerlendirmiştir?', 'Ağır cezayla tehdit edilenlere göre daha az çekici', ['Ağır cezayla tehdit edilenlere göre daha çekici', 'Tehdit edilmeyenlerle tamamen aynı', 'Oyuncakla hemen oynamaya başlayacak kadar çekici'], 'Hafif tehdit uymayı açıklamaya yetmediğinden çocuklar \'Zaten o kadar istemiyorum\' diye düşünerek oyuncağı küçümsemiştir; buna yetersiz ceza etkisi denir.'),
  ('Bir anne-baba, çocuğunun kardeşine vurmamasını sağlamak için çok sert bir ceza yerine yalnızca hafif bir uyarıda bulunmayı tercih ediyor. Yetersiz ceza araştırmalarına göre bu yaklaşımın olası yararı hangisidir?', 'Çocuğun vurmamayı kendi değeri olarak içselleştirmesi', ['Çocuğun cezadan daha çok korkması', 'Çocuğun vurmayı yalnızca ebeveyni yanındayken bırakması', 'Çocuğun kardeşine daha çok kızması'], 'Hafif bir dış neden davranışı tam açıklayamadığında çocuk uyumunu iç gerekçelerle açıklar ve tutumunu kalıcı biçimde değiştirir.'),
  ('Bilişsel çelişki kuramına göre bir kişi kendi tutumuna aykırı bir davranışı hangi durumda en fazla çelişki yaşar?', 'Davranışı özgürce seçtiğinde ve davranışın öngörülebilir olumsuz sonuçları olduğunda', ['Davranış zorla yaptırıldığında', 'Davranış için çok yüksek bir ödül aldığında ve bunu herkes bildiğinde', 'Davranışın hiçbir sonucu olmadığında'], 'Seçim özgürlüğü ve sorumluluk algısı, davranışı dış etkenlere yüklemeyi zorlaştırdığı için çelişkiyi artırır.'),
  ('Fritz Heider\'in denge kuramına göre Ayşe Burak\'ı seviyor, Burak caz müziğini seviyor, ancak Ayşe cazdan hoşlanmıyor. Bu üçlü ilişki için ne söylenebilir?', 'Dengesizdir; Ayşe tutumlarından birini değiştirme eğilimi duyabilir', ['Dengelidir; hiçbir değişime gerek yoktur', 'Dengelidir; çünkü iki ilişki olumludur', 'Denge kuramının kapsamı dışındadır'], 'Denge kuramında üç ilişkinin işaretlerinin çarpımı olumluysa denge vardır; burada (+)(+)(-) çarpımı olumsuz olduğundan sistem dengesizdir.'),
  ('Heider\'in denge kuramına göre \'düşmanımın düşmanı dostumdur\' ifadesi neden dengeli bir durum oluşturur?', 'Üç ilişkinin işaretlerinin çarpımı olumlu olduğu için', ['İlişkilerin tümü olumlu olduğu için', 'İlişkilerin tümü olumsuz olduğu için', 'Kişiler arasında hiçbir duygusal ilişki bulunmadığı için'], 'Ben-düşman (-), düşman-onun düşmanı (-), ben-o kişi (+) ilişkilerinin çarpımı olumlu olduğundan durum dengelidir.'),
  ('Heider\'in denge kuramının bilişsel çelişki kuramıyla paylaştığı temel varsayım hangisidir?', 'İnsanların bilişleri arasında tutarlılık arama eğiliminde olduğu', ['İnsanların her zaman çelişkiden ve tutarsızlıktan hoşlandığı', 'Tutumların hiç değişmediği', 'Davranışın yalnızca ödüllerle belirlendiği'], 'İki kuram da bilişsel tutarlılık kuramları ailesindedir ve tutarsızlığın değişim için güdüleyici bir gerilim yarattığını öne sürer.'),
  ('Carl Hovland ve arkadaşlarının Yale Üniversitesi\'nde yürüttüğü ikna araştırmaları ikna sürecini hangi soruyla özetlemiştir?', 'Kim, neyi, kime söylüyor?', ['Ne zaman, nerede, neden?', 'Kaç kişi, ne kadar süre, hangi ortamda?', 'Hangi duygu, hangi düşünce, hangi davranış?'], 'Yale yaklaşımı iknayı kaynak (kim), mesaj (ne) ve alıcı (kime) özellikleri üzerinden incelemiştir.'),
  ('Uyuyan etkinin ortaya çıkmasının en önemli nedeni hangisidir?', 'Kişinin mesajı hatırlayıp kaynağın güvenilmezliğini unutması', ['Mesajın zamanla değişmesi', 'Kaynağın sonradan araştırılıp güvenilir bir kaynak haline gelmesi', 'Kişinin mesajı tamamen unutması'], 'Kaynak ipucu mesajdan daha hızlı unutulduğunda, başlangıçta iknayı engelleyen \'güvenilmez kaynak\' etkisi ortadan kalkar.'),
  ('Korku uyandıran sağlık mesajlarının davranış değişikliğine yol açması için araştırmalara göre hangi öğeyi de içermesi önemlidir?', 'Tehlikeden korunmak için uygulanabilir ve etkili bir öneri', ['Mümkün olan en yüksek düzeyde ve sürekli tekrarlanan korku', 'Hiçbir somut bilgi vermeyen genel uyarı', 'Yalnızca istatistik tabloları'], 'Korku çağrıları, kişiye tehdidi azaltacak açık ve yapılabilir bir yol gösterildiğinde etkilidir; aksi halde inkâr ve kaçınma görülebilir.'),
  ('Konuşmacının hızlı konuşmasının dinleyicilerde onu daha bilgili ve güvenilir algılamaya yol açabildiği bulgusu, iknada hangi değişken grubuna girer?', 'Kaynak özellikleri', ['Alıcı (dinleyici) özellikleri', 'Ortam özellikleri', 'Kanal özellikleri'], 'Konuşma hızı, kaynağın yetkinlik ve güvenilirlik algısını etkileyen bir kaynak özelliği olarak incelenmiştir.'),
  ('Bir kişinin, kendi çıkarına aykırı görünen bir görüşü savunduğunda daha inandırıcı bulunması iknada hangi ilkeyle açıklanır?', 'Kaynağın çıkar gözetmiyor görünmesi güvenilirliği artırır', ['Kaynağın uzmanlığı her zaman düşer', 'Mesaj daha uzun ve ayrıntılı olduğu için her durumda daha çok ikna eder', 'Dinleyiciler kaynağı hiç dikkate almaz'], 'Örneğin bir suçlunun daha sert cezaları savunması, kişisel çıkarı olmadığı düşünüldüğü için daha inandırıcı bulunur.'),
  ('Ayrıntılandırma Olasılığı Modeli\'ne göre merkezi yolla oluşan tutum değişikliğinin çevresel yolla oluşana göre özelliği hangisidir?', 'Daha kalıcı, karşı iknaya dirençli ve davranışı daha iyi yordayan olması', ['Daha kısa süreli ve kolay değişebilir olması', 'Hiçbir zaman davranışa yansımaması', 'Yalnızca çocuklarda görülmesi'], 'Dikkatli düşünmeyle oluşan tutumlar bilişsel olarak daha iyi desteklendiğinden daha güçlü ve kararlıdır.'),
  ('Ayrıntılandırma Olasılığı Modeli\'ne göre bir kişinin merkezi yolu kullanması için gereken iki temel koşul hangileridir?', 'Mesajı düşünmeye güdülenmiş ve bunu yapabilecek durumda olması', ['Kaynağın çekici ve ünlü olması', 'Mesajın kısa ve renkli olması', 'Kişinin yorgun, aceleci ve dikkati dağınık olması'], 'Kişisel ilgi gibi etkenler güdülenmeyi, dikkat dağıtıcıların yokluğu ve bilgi düzeyi ise yeteneği belirler; ikisi de varsa merkezi yol işler.'),
  ('William McGuire\'ın aşılama kuramına göre bir kişiyi güçlü bir ikna girişimine karşı korumanın yolu hangisidir?', 'Önce zayıf karşı argümanlarla karşılaştırıp bunları çürütmesini sağlamak', ['Kişiyi hiçbir karşı görüşle karşılaştırmamak', 'Kişiye yalnızca kendi görüşünü destekleyen bilgileri tekrar tekrar vermek', 'Kişiyi uzun süre yalnız bırakmak'], 'Aşı benzetmesine göre zayıf bir saldırıya maruz kalan kişi savunma geliştirir ve sonraki güçlü saldırıya karşı daha dirençli olur.'),
  ('Jack Brehm\'in tepkisellik (reaktans) kuramına göre bir kişi özgürlüğünün kısıtlandığını hissettiğinde ne olur?', 'Yasaklanan seçeneği daha çekici bulup ona yönelir', ['Kısıtlamayı hemen ve içtenlikle benimseyip savunmaya başlar', 'Tüm seçeneklere ilgisini yitirir', 'Kısıtlamayı koyanı daha çok sever'], 'Tepkisellik, tehdit edilen davranış özgürlüğünü yeniden kazanmak için kişinin istenenin tersini yapma güdüsüdür.'),
  ('Bir dinleyici kitlesine kendilerini ikna etmeye çalışacak bir konuşma yapılacağının önceden bildirilmesi, özellikle konu onlar için önemliyse iknayı nasıl etkiler?', 'Karşı argüman hazırlamalarına fırsat verip iknayı azaltır', ['Dinleyicilerin dikkatini artırdığı için iknayı kesin olarak artırır', 'Hiçbir etki yapmaz', 'Dinleyicileri konuşmacıya bağımlı kılar'], 'Ön uyarı, dinleyicilerin tutumlarını savunmak için önceden karşı düşünceler üretmesine yol açar.'),
  ('Bir ikna konuşması sırasında dinleyicilerin dikkatinin hafifçe dağıtılmasının, bazı durumlarda iknayı artırabilmesi nasıl açıklanır?', 'Dinleyicilerin karşı argüman üretmesinin engellenmesiyle', ['Dinleyicilerin mesajı daha iyi anlamasıyla', 'Konuşmacının daha güvenilir ve daha bilgili görünmesiyle', 'Mesajın daha kısa algılanmasıyla'], 'Hafif dikkat dağınıklığı karşı düşünce üretimini engeller; ancak dikkat çok dağılırsa mesaj hiç anlaşılmayacağından ikna yine düşer.'),
  ('Cialdini\'nin bağlılık ve tutarlılık ilkesine göre, bir kişinin bağlılığını yazılı ve herkesin önünde açıklaması neden daha etkilidir?', 'Kişinin sonradan bu bağlılıkla tutarlı davranma baskısını artırdığı için', ['Kişinin bağlılığını daha çabuk unutmasını sağladığı için', 'Başkalarının kişiyi daha az izlemesine yol açtığı için', 'Kişinin karar vermesini zorlaştırıp onu kararsızlığa sürüklediği için'], 'Etkin, kamusal ve çaba gerektiren bağlılıklar kişinin benlik algısını değiştirir ve tutarlı davranma isteğini güçlendirir.'),
  ('Uyum sağlatma teknikleri arasında \'ayağını kapıya sokma\' tekniğinin işe yaramasını en iyi açıklayan kuram hangisidir?', 'Öz algı kuramı', ['Gerçekçi çatışma kuramı', 'Sosyal kimlik kuramı', 'Engellenme-saldırganlık kuramı'], 'Küçük isteği kabul eden kişi kendini \'yardımsever biri\' olarak algılamaya başlar ve bu benlik algısına uygun olarak büyük isteği de kabul eder.'),
  ('Sherif\'in otokinetik deneylerinde, ışığın hareket miktarını önce tek başına sonra grup içinde tahmin eden katılımcıların tahminlerine ne olmuştur?', 'Ortak bir grup normunda birleşmiştir', ['Birbirinden giderek uzaklaşarak tamamen farklılaşmıştır', 'Hiç değişmemiştir', 'Tamamen sıfıra inmiştir'], 'Belirsiz bir durumda bireyler birbirlerinin tahminlerini bilgi kaynağı olarak kullanmış ve tahminleri ortak bir normda toplanmıştır.'),
  ('Sherif\'in deneylerinde grup içinde oluşan normun, katılımcılar sonradan yeniden tek başına test edildiğinde de sürmesi, uymanın hangi niteliğini gösterir?', 'Grubun yargısının içselleştirildiğini', ['Uymanın yalnızca dışsal ve geçici bir boyun eğme olduğunu', 'Katılımcıların grubu unuttuğunu', 'Normun anında ortadan kalktığını'], 'Kişiler grup yokken de grup normunu kullanmaya devam ettiklerinden, belirsiz durumdaki uyma özel kabul düzeyinde, yani içselleştirilmiştir.'),
  ('Sherif\'in otokinetik deneyi ile Asch\'in çizgi deneyini karşılaştırdığımızda, iki deneyde baskın olan sosyal etki türleri sırasıyla hangileridir?', 'Bilgisel etki; normatif etki', ['Normatif etki; bilgisel etki', 'İkisinde de yalnızca bilgisel etki', 'İkisinde de yalnızca itaat'], 'Sherif\'in belirsiz uyarıcısı doğruyu bulmak için gruba başvurmayı (bilgisel), Asch\'in açık uyarıcısı ise grubun onayını kaybetmeme kaygısını (normatif) öne çıkarır.'),
  ('Asch\'in çizgi deneyinin bir çeşitlemesinde katılımcıların yanıtlarını yüksek sesle değil, yazılı ve gizli olarak vermesi istenmiştir. Bu değişiklik uymayı nasıl etkilemiştir?', 'Uyma belirgin biçimde azalmıştır', ['Uyma belirgin biçimde artmıştır', 'Uyma hiç değişmemiştir', 'Katılımcılar yanıt vermeyi reddetmiştir'], 'Yanıtların gizli olması grup onayını kaybetme kaygısını ortadan kaldırdığı için normatif etkiye dayalı uymayı azaltmıştır.'),
  ('Asch\'in deneyinde katılımcıların yaklaşık dörtte üçünün en az bir kez gruba uyduğu, ancak yaklaşık dörtte birinin hiç uymadığı bulunmuştur. Bu sonuçtan çıkarılabilecek en doğru yargı hangisidir?', 'Grup baskısı güçlüdür, ancak bireyler arasında belirgin farklar vardır', ['İnsanların tamamının her durumda ve her koşulda gruba uyduğu', 'Grup baskısının hiçbir etkisi yoktur', 'Uyma yalnızca kişiliğe bağlıdır'], 'Sonuçlar hem durumsal baskının gücünü hem de bireysel farklılıkların varlığını göstermektedir.'),
  ('Kelman\'ın üç sosyal etki sürecini kalıcılık bakımından en kısa süreliden en kalıcıya doğru sıralayan seçenek hangisidir?', 'Boyun eğme, özdeşleşme, içselleştirme', ['İçselleştirme, özdeşleşme, boyun eğme', 'Özdeşleşme, boyun eğme, içselleştirme', 'Boyun eğme, içselleştirme, özdeşleşme'], 'Boyun eğme gözetim varken sürer, özdeşleşme ilişki sürdükçe korunur, içselleştirme ise kişinin değer sistemine yerleştiği için en kalıcıdır.'),
  ('Moscovici\'ye göre çoğunluk etkisi ile azınlık etkisi arasındaki temel fark hangisidir?', 'Çoğunluk daha çok kamusal uymaya, azınlık ise daha derin ve özel düşünce değişimine yol açar', ['Çoğunluk etkisi her zaman özel kabul, azınlık etkisi her zaman yüzeysel boyun eğmedir', 'İkisi arasında hiçbir fark yoktur', 'Azınlık hiçbir zaman etki yaratamaz'], 'Azınlık, insanları konuyu yeniden düşünmeye yöneltir; bu nedenle etkisi gecikmeli ve dolaylı olsa da içsel bir değişime yol açabilir.'),
  ('Edwin Hollander\'ın \'kişisel kredi\' kavramına göre bir grup üyesi hangi durumda grup normlarından sapmaya başlarsa grubu daha kolay etkiler?', 'Önce uzun süre normlara uyarak güven ve saygınlık kazandıktan sonra', ['Gruba katıldığı ilk gün sapmaya başlarsa', 'Hiçbir zaman normlara uymamış ve hep muhalif davranmışsa', 'Grup tarafından dışlandıktan sonra'], 'Hollander\'a göre normlara uyarak biriktirilen \'krediler\', kişinin sonradan yenilik önerdiğinde dışlanmadan etkili olmasını sağlar.'),
  ('Milgram\'ın itaat deneylerinde katılımcı ile öğrenci rolündeki kişi aynı odaya alındığında ve katılımcı öğrenciyi görüp duyabildiğinde, itaat oranı temel duruma göre nasıl değişmiştir?', 'Belirgin biçimde azalmıştır', ['Belirgin biçimde artmıştır', 'Hiç değişmemiş, aynı düzeyde kalmıştır', 'Yüzde 100\'e ulaşmıştır'], 'Kurbanın yakınlığı arttıkça itaat azalmış; aynı odada yaklaşık yüzde 40\'a, katılımcının öğrencinin elini şok plakasına bastırması gereken durumda yaklaşık yüzde 30\'a düşmüştür.'),
  ('Milgram, deneyi Yale Üniversitesi yerine Bridgeport kentindeki sıradan bir iş hanında, belirsiz bir araştırma şirketi adına tekrarladığında itaat oranı ne olmuştur?', 'Bir miktar düşmüş, ancak yine de yarıya yakın kalmıştır', ['Sıfıra inmiştir', 'Yüzde 100\'e çıkmıştır', 'Temel durumla tamamen aynı kalmış, hiçbir değişiklik görülmemiştir'], 'Bridgeport çeşitlemesinde itaat yaklaşık yüzde 48\'e düşmüştür; bu, kurumun saygınlığının etkili olduğunu ama tek etken olmadığını gösterir.'),
  ('Milgram\'ın bir çeşitlemesinde, katılımcıyla birlikte öğretmen rolünü üstlenen iki iş birlikçi belirli bir noktada deneye devam etmeyi reddetmiştir. Bu durumda katılımcıların itaat oranına ne olmuştur?', 'Çarpıcı biçimde düşmüştür', ['Belirgin biçimde artmıştır', 'Hiç değişmemiştir', 'Önce artmış sonra sabitlenmiştir'], 'Başkaldıran akranların varlığı, katılımcılara itaat etmeme konusunda model olmuş ve itaat oranı yaklaşık yüzde 10\'a inmiştir.'),
  ('Milgram\'ın itaat deneylerinde şok düzeylerinin 15 voltluk küçük adımlarla artırılması, katılımcıların devam etmesini kolaylaştırmıştır. Bu durum hangi ilkeyle ilişkilendirilebilir?', 'Aşamalı bağlılık, yani küçük adımlarla ilerlemenin geri dönüşü zorlaştırması', ['Kıtlık ilkesi, yani azalan seçeneklerin daha değerli görünmesi', 'Salt maruz kalma etkisi', 'Aşılama kuramı'], 'Her adımın bir öncekinden pek farklı olmaması, katılımcının \'Bir önceki doğruydu da bu neden yanlış olsun?\' diye düşünmesine yol açarak devam etmeyi kolaylaştırır.'),
  ('Milgram\'ın bir çeşitlemesinde şoku katılımcı değil başka bir kişi verirken katılımcı yalnızca yardımcı görevleri yapmıştır. Bu durumda deneye sonuna kadar katılanların oranı nasıl olmuştur?', 'Çok yükselmiştir', ['Sıfıra inmiştir', 'Belirgin biçimde düşmüştür', 'Yarı yarıya azalmıştır'], 'Doğrudan şok vermeyen katılımcıların yaklaşık yüzde 92\'si sona kadar devam etmiş; sorumluluğun dağılması itaati kolaylaştırmıştır.'),
  ('Robert Zajonc\'un 1965\'te önerdiği açıklamaya göre başkalarının varlığı performansı hangi mekanizmayla etkiler?', 'Fizyolojik uyarılmayı artırarak baskın tepkiyi güçlendirir', ['Kişinin dikkatini tamamen kapatır', 'Kişinin motivasyonunu her zaman ve her görevde düşürür', 'Kişinin bellek kapasitesini artırır'], 'Zajonc\'a göre başkalarının varlığı uyarılmayı artırır; uyarılma da iyi öğrenilmiş görevlerde doğru, yeni görevlerde ise yanlış baskın tepkileri ortaya çıkarır.'),
  ('Sosyal kolaylaştırmayı açıklayan \'dikkat dağıtma-çatışma\' kuramına göre izleyiciler performansı nasıl etkiler?', 'Dikkatin görev ile izleyiciler arasında bölünmesi bir çatışma ve uyarılma yaratır', ['İzleyiciler kişiyi tamamen rahatlatır', 'İzleyiciler kişiye görevi kolaylaştırıcı ipuçları verir ve onu yönlendirir', 'İzleyiciler kişinin uyarılmasını azaltır'], 'Robert Baron\'un kuramına göre dikkat çatışması uyarılmayı artırır; bu da basit görevlerde performansı yükseltir, karmaşık görevlerde düşürür.'),
  ('Ringelmann etkisinde kişi başına düşen performansın azalması iki nedenle açıklanır. Bunlardan biri güdülenme kaybıdır. Diğeri hangisidir?', 'Üyelerin çabalarını eş zamanlı birleştirememesinden doğan eşgüdüm kaybı', ['Grup üyelerinin daha fazla bilgiye ve deneyime sahip olması nedeniyle rahatlama', 'Grup liderinin olmaması', 'Görevin daha kolay hale gelmesi'], 'Halat çekmede herkes tam aynı anda ve aynı yönde çekemediği için eşgüdüm kaybı oluşur; buna ek olarak çaba da azalır.'),
  ('Sosyal kaytarmanın hangi tür kültürlerde daha zayıf olduğu, hatta bazen tersine döndüğü bulunmuştur?', 'Toplulukçu kültürlerde', ['Bireyci kültürlerde', 'Sanayileşmiş Batı kültürlerinde', 'Kültürden bağımsız her yerde eşit'], 'Karau ve Williams\'ın meta-analizine göre grup başarısını önemseyen toplulukçu kültürlerde sosyal kaytarma daha az görülür.'),
  ('Tuckman\'ın grup gelişimi modelinin evreleri doğru sırayla hangi seçenekte verilmiştir?', 'Oluşma, çatışma, norm oluşturma, performans', ['Çatışma, oluşma, performans, norm oluşturma', 'Oluşma, norm oluşturma, çatışma, performans', 'Norm oluşturma, oluşma, çatışma, performans'], 'Model önce tanışma, sonra çatışma, ardından uzlaşı ve kuralların yerleşmesi, en sonunda verimli çalışma evrelerini öngörür.'),
  ('Bir grubun üyelerinin birbirine karşı duyduğu çekim ve grupta kalma isteği arttıkça, grubun normlarına uyma baskısının nasıl değişmesi beklenir?', 'Artması', ['Azalması', 'Hiç değişmemesi', 'Tamamen ortadan kalkması'], 'Uyumu (kenetlenmesi) yüksek gruplarda üyeler gruba değer verdikleri için grup normlarına uyma eğilimi ve sapanlara yönelik baskı daha güçlüdür.'),
  ('Zorlu ve küçük düşürücü bir giriş töreninden geçen yeni üyelerin gruba daha çok bağlanması sosyal psikolojide hangi kuramla açıklanır?', 'Bilişsel çelişki kuramı', ['Sosyal karşılaştırma kuramı', 'Gerçekçi çatışma kuramı', 'Kovaryasyon modeli'], 'Çok acı çekilen bir şeyin değersiz olduğunu kabul etmek çelişki yaratacağından, üye gruba daha fazla değer biçer.'),
  ('Irving Janis\'in 1972 tarihli kitabında grup düşüncesine örnek olarak incelediği ABD dış politika kararlarından biri hangisidir?', '1961 Domuzlar Körfezi çıkarması', ['1969 Ay\'a iniş', '1945 Birleşmiş Milletler\'in kuruluşu', '1948 Marshall Planı\'nın başlatılması'], 'Janis, Kennedy yönetiminin Küba\'ya yönelik başarısız Domuzlar Körfezi çıkarmasını, grup içi uyum baskısının eleştirel düşünceyi bastırdığı bir örnek olarak incelemiştir.'),
  ('Janis\'in grup düşüncesi belirtileri arasında yer alan \'zihin bekçileri\' ne yapar?', 'Grubu, aldığı kararı sorgulatacak bilgilerden korur', ['Grubu dış tehditlere karşı silahla korur', 'Toplantı notlarını tutar ve bunları arşivleyip saklar', 'Grup üyelerine ödül dağıtır'], 'Zihin bekçileri, liderin ya da grubun karara olan güvenini sarsabilecek karşıt bilgileri süzen kendiliğinden atanmış üyelerdir.'),
  ('Stasser ve Titus\'un \'gizli profil\' çalışmaları, grup tartışmalarında hangi eğilimi ortaya koymuştur?', 'Herkesin bildiği ortak bilgilerin konuşulup yalnızca bir üyenin bildiği bilgilerin göz ardı edilmesi', ['Her üyenin yalnızca kendi özel bilgisini paylaşması', 'Grupların bireylerden her zaman daha iyi karar vermesi', 'Tartışmanın üyelerin bilgisini hiç etkilememesi'], 'Ortak bilgi etkisi denilen bu eğilim, en iyi seçeneği gösteren bilgilerin farklı üyelere dağıldığı durumlarda grupların kötü karar vermesine yol açar.'),
  ('Beyin fırtınası araştırmalarında, birlikte fikir üreten gruplar ile aynı sayıda kişinin tek tek ürettiği fikirlerin toplamı karşılaştırıldığında genellikle hangi sonuç bulunmuştur?', 'Tek tek çalışanların toplamı daha çok ve daha özgün fikir üretmiştir', ['Gruplar her zaman bireylerin toplamından iki kat daha fazla fikir üretmiştir', 'İki durumda da fikir sayısı tamamen eşittir', 'Gruplar hiç fikir üretememiştir'], 'Sıra bekleme, değerlendirilme kaygısı ve sosyal kaytarma gibi nedenlerle sözlü beyin fırtınası gruplarında üretkenlik kaybı yaşanır.'),
  ('Fred Fiedler\'in olasılık (durumsallık) modeline göre liderliğin etkililiği neye bağlıdır?', 'Liderin tarzı ile durumun lidere sağladığı denetim düzeyinin uyumuna', ['Yalnızca liderin zekâsına', 'Yalnızca üyelerin sayısına', 'Liderin yaşına, deneyimine ve eğitim düzeyine'], 'Fiedler\'e göre görev odaklı liderler durum çok elverişli ya da çok elverişsizken, ilişki odaklı liderler orta düzeyde elverişli durumlarda daha etkilidir.'),
  ('Fiedler\'in modeline göre, liderle üyelerin ilişkisinin çok kötü, görevin belirsiz ve liderin yetkisinin zayıf olduğu bir durumda hangi lider tipinin daha etkili olması beklenir?', 'Görev odaklı lider', ['İlişki odaklı lider', 'Serbest bırakıcı lider', 'Hiçbir lider tipi fark yaratmaz'], 'Durum lider için çok elverişsiz olduğunda, düzen kurup işi yönlendiren görev odaklı liderler daha iyi sonuç alır.'),
  ('Mahkûm ikileminde iki şüpheliden her biri için, diğerinin ne yapacağından bağımsız olarak bireysel açıdan en kazançlı görünen seçim hangisidir?', 'Diğerini ele vermek', ['Susmak', 'Kurayla karar vermek', 'Avukatı beklemek'], 'Diğeri sussa da itiraf etse de, ele vermek bireye daha az ceza sağlar; ancak ikisi de bunu seçtiğinde ortak sonuç, ikisinin de sustuğu durumdan kötüdür.'),
  ('Mahkûm ikilemini \'sosyal ikilem\' yapan temel özellik hangisidir?', 'Herkes bireysel çıkarını seçtiğinde herkesin daha kötü duruma düşmesi', ['Oyuncuların birbirini hiç tanımaması', 'Tek bir doğru seçeneğin bulunmaması', 'Oyunun yalnızca bir kez oynanması ve sonucun önceden bilinmesi'], 'Sosyal ikilemlerde bireysel olarak akılcı görünen seçimler toplu düzeyde herkes için daha kötü sonuç doğurur.'),
  ('Garrett Hardin\'in 1968\'de ortak bir meraya her çobanın kendi çıkarı için daha fazla hayvan salmasıyla meranın tükenmesi örneğiyle anlattığı ikilem hangisidir?', 'Ortak malların trajedisi', ['Mahkûm ikilemi', 'Kamu malı ikilemi', 'Tavuk oyunu'], 'Herkesin kullanabildiği sınırlı bir kaynağı bireylerin aşırı tüketmesi kaynağın tükenmesine ve herkesin zarar görmesine yol açar.'),
  ('Kamu yayın kuruluşlarına bağış yapmadan onların yayınlarından yararlanmak, sosyal ikilemlerin hangi türüne örnektir?', 'Kamu malı ikilemi', ['Ortak malların trajedisi', 'Mahkûm ikilemi', 'Kapıyı yüzüne çarpma tekniği'], 'Kamu malı ikileminde herkesin katkısıyla sağlanan bir yarardan, katkı yapmayanlar da yararlanabildiği için katkı vermeme eğilimi doğar.'),
  ('Sherif\'in Robbers Cave çalışmasında \'Kartallar\' ve \'Çıngıraklı Yılanlar\' adlı gruplar arasındaki düşmanlık hangi aşamada ortaya çıkmıştır?', 'Ödüllü yarışmaların düzenlendiği rekabet aşamasında', ['Grupların birbirinden habersiz olduğu ilk hafta', 'Ortak hedeflerin verildiği son aşamada', 'Kamp sona erip eve dönüldüğünde'], 'Gruplar önce ayrı ayrı oluşturulmuş, ardından ödüllü yarışmalarla rekabete sokulunca bayrak yakma ve baskın gibi düşmanca davranışlar başlamıştır.'),
  ('Robbers Cave çalışmasında grupların yalnızca bir arada film izlemesi ve yemek yemesi gibi temaslar düşmanlığı neden azaltmamıştır?', 'Temas ortak bir amaç içermediği için çatışmalara fırsat yaratmıştır', ['Çocuklar bu etkinliklerde birbirini hiç görmediği için', 'Etkinlikler çok uzun sürdüğü için', 'Grupların liderleri yasakladığı için'], 'Salt temas, iş birliği gerektiren bir amaç olmadığında yemek kavgaları gibi yeni çatışmalara dönüşmüştür.'),
  ('Charles Osgood\'un uluslararası gerginliği azaltmak için önerdiği GRIT stratejisinin temel fikri hangisidir?', 'Bir tarafın küçük ve açıklanmış uzlaşma adımları atıp karşı tarafı karşılık vermeye çağırması', ['İki tarafın silahlanmayı en üst düzeye çıkarması', 'Tarafların her türlü iletişimi kesmesi', 'Bir tarafın tüm taleplerinden koşulsuz vazgeçmesi'], 'Gerilimi azaltmak için aşamalı ve karşılıklı girişimler anlamına gelen GRIT, karşılıklılık normunu kullanarak güven inşa etmeyi amaçlar.'),
  ('Henri Tajfel\'in \'minimal grup\' deneylerinde öğrenciler hangi önemsiz ölçüte göre gruplara ayrılmıştır?', 'Klee ya da Kandinsky resimlerinden hangisini beğendiklerine', ['Okul başarılarına, sınav notlarına ve öğretmen değerlendirmelerine', 'Ailelerinin gelir düzeyine', 'Doğdukları şehirlere ve bölgelere'], 'Tajfel öğrencileri resim tercihi gibi anlamsız bir ölçütle ayırmış, aslında atamaları rastgele yapmıştı; buna karşın öğrenciler kendi gruplarını kayırmıştır.'),
  ('Minimal grup deneylerinin sosyal psikoloji açısından en çarpıcı sonucu hangisidir?', 'Salt bir gruba ait olma bilgisinin bile iç grup kayırmacılığı yaratması', ['Grupların kaynak rekabeti olmadan hiç ayrımcılık yapmaması', 'Katılımcıların gruplara tamamen eşit puan dağıtması', 'Grupların birbirini yakından tanıdıkça kayırmacılığın belirgin biçimde arttığı'], 'Rekabet, geçmiş ya da yüz yüze etkileşim olmadan bile insanlar kendi gruplarına daha çok ödül vermiş; bu da kategorileştirmenin tek başına ayrımcılığa yetebileceğini göstermiştir.'),
  ('Minimal grup deneylerinde katılımcıların çoğu zaman iç gruba en yüksek mutlak kazancı sağlayan seçenek yerine, iki grup arasındaki farkı en çok açan seçeneği tercih etmesi neyi gösterir?', 'Göreli üstünlük sağlamanın mutlak kazançtan daha önemli görülebildiğini', ['Katılımcıların basit matematik hesaplarını bile doğru yapamadığını', 'İç grubun tamamen önemsiz görüldüğünü', 'Tüm katılımcıların eşitliği savunduğunu'], 'Katılımcılar kendi grupları daha az kazansa bile dış gruptan daha fazla kazanmasını sağlayan dağıtımları seçmiştir; bu, olumlu ayırt ediciliğe yönelik bir güdüyü gösterir.'),
  ('Tajfel ve Turner\'ın sosyal kimlik kuramına göre insanlar neden iç gruplarını kayırma eğilimindedir?', 'Olumlu bir sosyal kimlik, dolayısıyla öz saygı kazanmak istedikleri için', ['Kıt kaynaklar için kaçınılmaz ve zorunlu bir rekabet içinde bulundukları için', 'Çocuklukta cezalandırıldıkları için', 'Dış grupları hiç tanımadıkları için'], 'Sosyal kimlik kuramına göre benlik kısmen grup üyeliklerinden oluşur; iç grubu olumlu görmek kişinin benlik saygısını yükseltir.'),
  ('Sosyal kimlik kuramında yer alan süreçlerin doğru sırası hangisidir?', 'Sosyal kategorileştirme, sosyal özdeşleşme, sosyal karşılaştırma', ['Sosyal karşılaştırma, ardından sosyal kategorileştirme, en son sosyal özdeşleşme', 'Sosyal özdeşleşme, sosyal karşılaştırma, sosyal kategorileştirme', 'Sosyal karşılaştırma, sosyal özdeşleşme, sosyal kategorileştirme'], 'İnsanlar önce kendilerini ve başkalarını kategorilere ayırır, sonra bir grupla özdeşleşir, ardından kendi gruplarını diğer gruplarla karşılaştırır.'),
  ('Sosyal kimlik kuramına göre, düşük statülü bir grubun üyesi olan bir kişinin grubunu bırakıp daha yüksek statülü bir gruba geçmeye çalışması hangi stratejidir?', 'Bireysel hareketlilik', ['Sosyal yaratıcılık', 'Sosyal rekabet', 'Sosyal kaytarma'], 'Grup sınırları geçirgen algılandığında kişiler grubu terk ederek bireysel olarak yükselmeye çalışır.'),
  ('Ekonomik olarak geride kalan bir kasaba halkının \'Biz daha zengin değiliz ama komşuluk ilişkilerimiz çok daha güçlü\' diyerek gururlanması, sosyal kimlik kuramına göre hangi stratejiye örnektir?', 'Sosyal yaratıcılık', ['Bireysel hareketlilik', 'Sosyal rekabet', 'Bilişsel çelişki'], 'Sosyal yaratıcılıkta grup, karşılaştırma boyutunu değiştirerek kendini olumlu değerlendirebileceği yeni bir ölçüt bulur.'),
  ('John Turner\'ın öz kategorileştirme kuramına göre bir kişinin kendini bir birey olarak değil de bir grubun üyesi olarak algılamaya başladığında gözlenen değişim hangisidir?', 'Kendini ve grup üyelerini grubun tipik özelliklerine göre algılamaya başlaması', ['Grubun özelliklerini tamamen unutması', 'Tüm dış grupları da kendi grubunun bir parçası saymaya başlaması', 'Kişisel kimliğinin güçlenmesi'], 'Kişi kendini grup üyesi olarak gördüğünde grubun prototipine göre algılanır ve davranır; buna kişisizleşme (depersonalizasyon) denir.'),
  ('Bir toplantıda tek kadın üye olan bir mühendisin söylediklerinin, cinsiyetiyle ilişkilendirilerek daha çok dikkat çekmesi ve abartılı yorumlanması hangi olgunun sonucudur?', 'Simge (belirgin azınlık) konumu', ['Sosyal kaytarma', 'Grup düşüncesi', 'Salt maruz kalma'], 'Bir grupta tek ya da çok az sayıda olan üyeler daha çok göze batar; bu kişiler grubunun temsilcisi olarak görülür ve kalıp yargılarla değerlendirilir.'),
  ('Otoriter kişilik yaklaşımına yöneltilen önemli bir eleştiri hangisidir?', 'Önyargıyı yalnızca bireysel kişilikle açıklayıp toplumsal ve durumsal etkenleri ihmal etmesi', ['Önyargının hiç var olmadığını savunması', 'Yalnızca hayvan deneylerine dayanması', 'Önyargıyı tamamen ekonomik koşullara ve gelir dağılımına bağlaması'], 'Bütün bir toplumda birdenbire yükselen önyargılar, örneğin savaş dönemlerindeki düşmanlık, kişilik farklarıyla açıklanamaz; bu da durumsal etkenlerin önemini gösterir.'),
  ('İnsanların zihinsel olarak birbirine benzeyen nesneleri ve kişileri gruplara ayırma eğiliminin önyargıyla ilişkisi en iyi nasıl açıklanır?', 'Dünyayı basitleştirir, ancak grup üyelerini birbirine benzer görmeye yol açabilir', ['Kategorileştirme önyargıyı tamamen ortadan kaldırır', 'Kategorileştirme yalnızca çocuklarda görülür', 'Kategorileştirmenin sosyal algıyla ve gruplara bakışla hiçbir ilgisi yoktur'], 'Kategorileştirme bilişsel olarak ekonomik bir süreçtir; ancak grup içi farkları küçültüp gruplar arası farkları büyüterek önyargının bilişsel temelini oluşturur.'),
  ('Gordon Allport\'un 1954\'te yayımlanan ve önyargı araştırmalarının temel eseri sayılan kitabının adı nedir?', 'The Nature of Prejudice', ['The Authoritarian Personality', 'Influence', 'Obedience to Authority'], 'Allport\'un bu eseri önyargının bilişsel, güdüsel ve toplumsal kaynaklarını ele almış, temas hipotezini de ilk kez sistemli biçimde ortaya koymuştur.'),
  ('Allport\'un önyargının dışavurum basamaklarını gösteren ölçeğinde en hafif düzeyden başlayan doğru sıralama hangisidir?', 'Kötü söz söyleme, kaçınma, ayrımcılık, fiziksel saldırı, yok etme', ['Kaçınma, kötü söz söyleme, fiziksel saldırı, ayrımcılık, yok etme', 'Ayrımcılık, kaçınma, kötü söz söyleme, yok etme, fiziksel saldırı', 'Fiziksel saldırı, ayrımcılık, kaçınma, kötü söz söyleme ve en son yok etme'], 'Allport\'a göre önyargı, grup hakkında kötü konuşmayla başlayıp kaçınma, ayrımcılık ve fiziksel saldırıya, en uç noktada ise soykırıma kadar varabilir.'),
  ('Patricia Devine\'ın 1989 çalışmasına göre düşük önyargılı kişiler ile yüksek önyargılı kişiler arasındaki temel fark nedir?', 'Her iki grup da kalıp yargıyı bilir; düşük önyargılılar onu bilinçli olarak bastırır', ['Düşük önyargılılar kalıp yargıları hiç bilmez', 'Kalıp yargıları otomatik olarak yalnızca yüksek önyargılılar etkinleştirir, ötekiler hiç etkinleştirmez', 'İki grup arasında hiçbir fark yoktur'], 'Devine\'a göre kalıp yargılar kültür yoluyla herkeste otomatik olarak etkinleşebilir; düşük önyargılı kişiler bunu denetimli düşünmeyle düzeltir.'),
  ('Bir kişinin açıkça eşitlikçi görüşleri savunmasına karşın Örtük İlişkilendirme Testi\'nde belirli bir gruba karşı olumsuz ilişkilendirmeler göstermesi nasıl yorumlanır?', 'Açık ve örtük tutumların birbirinden farklı olabileceği', ['Kişinin anketlerde kesinlikle ve bilerek yalan söylediği', 'Testin hiçbir şey ölçmediği', 'Kişinin hiçbir tutuma sahip olmadığı'], 'Örtük tutumlar otomatik çağrışımları, açık tutumlar ise bilinçli değerlendirmeleri yansıtır; ikisi her zaman örtüşmeyebilir.'),
  ('Daniel Katz ve Kenneth Braly\'nin 1933\'te Princeton Üniversitesi öğrencileriyle yaptığı çalışma neyi incelemiştir?', 'Etnik gruplara atfedilen kalıp yargı sıfatlarını', ['Öğrencilerin ders başarısını etkileyen ailevi etkenleri', 'Kampüste arkadaşlık ağlarının nasıl kurulduğunu', 'Öğrencilerin siyasi parti tercihlerini ve oy davranışlarını'], 'Katz ve Braly öğrencilerden farklı uluslara ve etnik gruplara uyan sıfatları seçmelerini istemiş ve yaygın kalıp yargıları ölçen ilk sistemli çalışmalardan birini yapmıştır.'),
  ('Kalıp yargıların tümüyle uydurma olmadığı, bazen gerçeklikten küçük bir pay taşıdığı görüşüne karşın, sosyal psikologların kalıp yargılara yönelik temel eleştirisi hangisidir?', 'Grup içindeki bireysel farklılıkları göz ardı edip herkese genellenmeleri', ['Her zaman tamamen doğru olmaları', 'Hiçbir zaman davranışı etkilememeleri', 'Yalnızca olumlu özellikler içermeleri ve bu yüzden zararsız olmaları'], 'Kalıp yargılar grup ortalamaları hakkında bir doğruluk payı taşısa bile tek tek kişilere uygulandığında yanlış ve haksız yargılara yol açar.'),
  ('\'Kadınlar sıcak ve şefkatlidir ama yetkin değildir\' gibi görünüşte olumlu ama aslında alt konumu pekiştiren kalıp yargılar hangi kavramla incelenir?', 'Korumacı (yardımsever) cinsiyetçilik', ['Düşmanca cinsiyetçilik', 'Yanlış teklik etkisi', 'Sosyal kaytarma'], 'Glick ve Fiske\'nin çelişik cinsiyetçilik kuramına göre korumacı cinsiyetçilik kadınları yüceltir görünse de onları geleneksel rollerle sınırlar.'),
  ('Kalıp yargı tehdidinin performansı düşürme mekanizması olarak öne sürülen etkenlerden biri hangisidir?', 'Kaygının çalışma belleğini meşgul etmesi', ['Kişinin görevi önceden hiç öğrenmemiş olması', 'Testin gerçekten daha zor olması', 'Kişinin görevden sıkılıp ilgisini kaybetmesi ve hiç uğraşmaması'], 'Kalıp yargıyı doğrulama kaygısı, olumsuz düşünceleri bastırma çabası ve fizyolojik uyarılma, görev için gereken bilişsel kaynakları azaltır.'),
  ('Damgalanmış bir grubun üyelerinin, aldıkları olumsuz geri bildirimi önyargıya bağlayabilmeleri bazı araştırmalarda neden öz saygıyı koruyucu bir işlev görebilir?', 'Başarısızlık kişinin yeteneğine değil dış bir nedene bağlandığı için', ['Geri bildirim her zaman doğru olduğu için', 'Kişi önyargıyı hiç fark etmediği için', 'Önyargı her zaman kişinin lehine işlediği için'], 'Crocker ve Major\'ın görüşüne göre olumsuz sonuçları ayrımcılığa yükleyebilmek, kişinin kendi yeteneğini sorgulamasını engelleyerek öz saygıyı koruyabilir.'),
  ('Elliot Aronson\'ın 1971\'de Austin\'deki okullarda geliştirdiği \'yapboz sınıf\' tekniğinde öğrencilere nasıl bir görev verilir?', 'Her biri konunun bir parçasını öğrenip diğerlerine öğretir', ['Her öğrenci tek başına bütün konuyu çalışıp en yüksek puanı almaya çalışır', 'Öğretmen bütün konuyu anlatır, öğrenciler yalnızca dinler', 'Öğrenciler gruplar halinde birbirleriyle yarışır ve kaybeden grup cezalandırılır'], 'Yapboz tekniğinde her öğrenci diğerlerinin bilgisine muhtaç olduğundan karşılıklı bağımlılık ve iş birliği oluşur; bu da gruplar arası önyargıyı azaltır.'),
  ('Yapboz sınıf uygulamasının bulgularına göre, bu yöntemle çalışan öğrencilerde hangi değişim gözlenmiştir?', 'Farklı gruplardan arkadaşlara karşı hoşlanmanın artması', ['Öğrencilerin okula devamsızlığının belirgin biçimde artması', 'Sınıf içi rekabetin ve kıskançlığın şiddetlenmesi', 'Azınlık öğrencilerinin öz saygısının düşmesi ve sınıftan uzaklaşması'], 'Yapboz sınıflarında öğrencilerin farklı etnik gruptan arkadaşlarını daha çok sevdiği, öz saygılarının arttığı ve azınlık öğrencilerinin başarısının yükseldiği bulunmuştur.'),
  ('Gaertner ve Dovidio\'nun \'ortak iç grup kimliği\' modeline göre gruplar arası önyargıyı azaltmanın yolu hangisidir?', 'İki grubu daha kapsayıcı tek bir \'biz\' kimliği altında yeniden kategorileştirmek', ['Grupları birbirinden tamamen ayırıp hiç karşılaştırmamak', 'Grupları kaynaklar için yarıştırmak', 'Kalıp yargıları yüksek sesle tekrarlamak'], 'İki grubun üyeleri kendilerini ortak bir üst grubun parçası olarak gördüklerinde eski dış grup üyeleri artık iç grup sayılır ve kayırmacılık onlara da yayılır.'),
  ('Öğretmen Jane Elliott\'un 1968\'de Martin Luther King\'in öldürülmesinin ertesi günü sınıfında yaptığı \'mavi gözler-kahverengi gözler\' uygulaması neyi göstermeyi amaçlamıştır?', 'Keyfi bir özelliğe dayalı ayrımcılığın nasıl hızla öğrenilip yaşandığını', ['Göz renginin zekâyı belirlediğini', 'Çocukların renkleri ayırt edemediğini', 'Sınıfların göz rengine göre ayrılmasının başarıyı artırdığını ve bunun sürdürülmesi gerektiğini'], 'Elliott bir gün mavi gözlüleri, ertesi gün kahverengi gözlüleri ayrıcalıklı yaparak çocuklara ayrımcılığın ne kadar keyfi ve yaralayıcı olduğunu yaşatmıştır.'),
  ('Sosyal psikolojide \'düşmanca saldırganlık\' ile \'araçsal saldırganlık\' arasındaki fark nedir?', 'Birincinin amacı zarar vermek, ikincinin zarar vermeyi başka bir amaca araç kılmaktır', ['Birincisi yalnızca sözlü, ikincisi yalnızca fiziksel saldırganlıktır', 'Birincisi hayvanlarda, ikincisi yalnızca insanlarda görülür', 'Birincisi kalıtsaldır, ikincisi tamamen öğrenilmiştir ve hiçbir duygu içermez'], 'Düşmanca saldırganlık öfkeden doğar ve zarar vermenin kendisini hedefler; araçsal saldırganlıkta ise zarar, para ya da statü gibi başka bir amaca ulaşmanın aracıdır.'),
  ('Konrad Lorenz\'in saldırganlığa ilişkin görüşü hangisidir?', 'Saldırganlık, türün hayatta kalmasına hizmet eden doğuştan bir içgüdüdür', ['Saldırganlık yalnızca model alma yoluyla öğrenilir', 'Saldırganlık yalnızca beyin hasarından kaynaklanır', 'Saldırganlık yalnızca sıcak iklimlerde görülen ve kültürle hiç ilgisi olmayan bir davranıştır'], 'Etolog Lorenz, \'Saldırganlık Üzerine\' adlı eserinde saldırganlığın hayvanlarda ve insanlarda evrimsel işlevi olan bir içgüdü olduğunu savunmuştur.'),
  ('Berkowitz\'in engellenme-saldırganlık hipotezini yeniden düzenlemesine göre engellenme her zaman saldırganlık doğurmaz. Saldırganlık olasılığını artıran etken hangisidir?', 'Engellenmenin yarattığı öfkeyle birlikte ortamda saldırganlık ipuçlarının bulunması', ['Kişinin engellenmeyi hiç fark etmemesi', 'Engellenmenin tamamen beklenen ve haklı bir nedene dayanması', 'Kişinin çok yorgun olması ve bu nedenle hiçbir şeye tepki vermemesi'], 'Berkowitz\'e göre engellenme olumsuz duygulanım ve saldırganlığa hazırlık yaratır; silah gibi ipuçları bu hazırlığı eyleme dönüştürebilir.'),
  ('Dolu bir otoparkta önüne geçilen bir sürücünün, yeni bitirdiği yoğun bir spor antrenmanının bedensel uyarılmasını da öfkesine katarak daha sert tepki vermesi Dolf Zillmann\'ın hangi kuramıyla açıklanır?', 'Uyarılma aktarımı kuramı', ['Sosyal kimlik kuramı', 'Denge kuramı', 'Planlı davranış kuramı'], 'Zillmann\'a göre bir kaynaktan gelen artık fizyolojik uyarılma, başka bir duruma yanlışlıkla aktarılıp o durumdaki duyguyu, örneğin öfkeyi, şiddetlendirebilir.'),
  ('Brad Bushman\'ın çalışmalarında, kızdırıldıktan sonra kum torbasını yumruklayan katılımcıların sonradan kendilerini kızdıran kişiye karşı nasıl davrandığı bulunmuştur?', 'Yumruklamayanlara göre daha saldırgan davranmışlardır', ['Tamamen sakinleşip hiç saldırganlık göstermemişlerdir', 'Kendilerini kızdıran kişiye özür dilemişlerdir', 'Saldırganlıkları yumruklamayanlarla tam olarak aynı düzeyde kalmış, hiç değişmemiştir'], 'Bulgular katarsis hipotezini desteklemez; saldırgan etkinlikle \'öfke boşaltma\', saldırgan düşünceleri canlı tutarak saldırganlığı artırabilir.'),
  ('Alkolün saldırgan davranışı artırmasına ilişkin en yaygın açıklama hangisidir?', 'Alkolün ketlemeyi azaltıp dikkati daraltarak durumun en belirgin ipuçlarına odaklatması', ['Alkolün kişiyi her zaman uykuya yatırması', 'Alkolün öfke duygusunu tamamen yok etmesi', 'Alkolün kişinin vicdani değerlerini ve ahlak bilincini kalıcı olarak değiştirmesi'], 'Steele ve Josephs\'in alkol miyopisi kavramına göre alkol, kişinin dikkatini kışkırtıcı ipuçlarına daraltır ve davranışın sonuçlarını düşünmeyi zorlaştırır.'),
  ('Uzun süreli çalışmalara göre çocuklukta çok fazla şiddet içerikli televizyon izlemek ile yetişkinlikteki saldırganlık arasında nasıl bir ilişki bulunmuştur?', 'Olumlu yönde bir ilişki', ['Olumsuz yönde bir ilişki', 'Hiçbir ilişki bulunmamış, iki değişken tamamen bağımsız', 'Yalnızca kız çocuklarında görülen ters yönde bir ilişki'], 'Huesmann ve Eron\'un boylamsal çalışmaları, çocuklukta izlenen şiddetin yıllar sonraki saldırganlıkla ilişkili olduğunu göstermiştir; ilişki neden-sonuç kesinliği taşımasa da tutarlıdır.'),
  ('Saldırganlıkta cinsiyet farklarına ilişkin araştırmalar genel olarak hangi sonucu ortaya koymuştur?', 'Erkekler daha çok fiziksel, kızlar daha çok ilişkisel saldırganlık gösterir', ['Kızlar fiziksel saldırganlıkta her yaşta erkeklerden belirgin biçimde üstündür', 'İki cinsiyet arasında saldırganlık türü bakımından hiçbir fark yoktur', 'Erkekler yalnızca sözel, kızlar yalnızca fiziksel saldırganlık gösterir'], 'Fiziksel saldırganlık erkeklerde daha sıktır; dedikodu ve dışlama gibi ilişkisel saldırganlıkta ise fark azalır ya da kızlar lehine döner.'),
  ('Saldırganlığı azaltmaya yönelik yöntemlerden hangisi araştırma bulgularıyla en çok desteklenmektedir?', 'Saldırgan olmayan tepkilerin modellenmesi ve öfke yönetimi becerilerinin öğretilmesi', ['Öfkenin kum torbasıyla düzenli olarak boşaltılması', 'Çocuklara daha çok şiddet içerikli oyun oynatılması', 'Saldırgan davranışların görmezden gelinip ödüllendirilmesi'], 'Sosyal öğrenme yaklaşımına göre empati, iletişim ve sorun çözme becerilerini öğreten modelleme ve eğitim, saldırganlığı azaltır.'),
  ('Dumanlı oda deneyinde katılımcıların yardım istememesinin temel nedeni hangisidir?', 'Başkalarının kayıtsızlığını durumun tehlikesiz olduğuna yorumlamaları', ['Dumanı hiç görmemeleri', 'Odadan çıkmalarının yasaklanmış olması', 'İş birlikçilerin onları dışarı çıkmamaları için açıkça tehdit etmesi'], 'Her katılımcı ötekilerin sakinliğine bakarak durumu yorumlamış; bu karşılıklı yanlış yorumlama çoğulcu bilgisizlik olarak adlandırılır.'),
  ('Darley ve Batson\'un 1973 \'İyi Samiriyeli\' deneyinde, İyi Samiriyeli öyküsü üzerine konuşma yapmak için başka bir binaya giden ilahiyat öğrencilerinin yolda yardıma muhtaç birine yardım edip etmemesini en çok belirleyen etken hangisidir?', 'Acele etmeleri gerekip gerekmediği', ['Konuşmalarının konusu', 'Dindarlık düzeyleri', 'Yaşları ve aldıkları ilahiyat eğitiminin süresi'], 'Acelesi olmayanların yaklaşık yüzde 63\'ü yardım ederken çok acele ettirilenlerde bu oran yaklaşık yüzde 10\'a düşmüştür; konuşma konusu belirgin fark yaratmamıştır.'),
  ('Isen ve Levin\'in 1972\'de yaptığı çalışmada, telefon kulübesinin bozuk para iadesi bölümünde para bulan kişilerin, hemen ardından kâğıtlarını düşüren birine yardım etme olasılığı daha yüksek bulunmuştur. Bu bulgu hangi olguyu gösterir?', 'İyi hissetme, iyilik yapma etkisi', ['Seyirci etkisi', 'Sosyal kaytarma', 'Çoğulcu bilgisizlik ve sorumluluk dağılması'], 'Olumlu ruh hali yardım etmeyi artırır; çünkü iyi hisseden insanlar dünyaya daha olumlu bakar ve bu ruh halini sürdürmek ister.'),
  ('Piliavin ve arkadaşlarının 1969 New York metrosu deneyinde vagonda yere düşen kişiye hangi durumda daha az ve daha geç yardım edilmiştir?', 'Kişi sarhoş göründüğünde', ['Kişi bastonlu ve hasta göründüğünde', 'Vagon kalabalık olduğunda', 'Kişi düştükten sonra hemen yardım istediğinde'], 'Bastonlu \'hasta\' kişiye çoğunlukla hemen yardım edilirken sarhoş görünen kişiye çok daha az yardım edilmiştir; bu, yardımın algılanan maliyet ve hak edişle ilişkisini gösterir.'),
  ('Piliavin\'in uyarılma-maliyet-ödül modeline göre bir tanık acil bir durumla karşılaştığında yardım kararını hangi etken belirler?', 'Yardım etmenin ve etmemenin maliyetlerinin karşılaştırılması', ['Yalnızca kişinin dindarlık düzeyi', 'Yalnızca mağdurun yaşı', 'Kişinin o günkü hava durumu ve sıcaklık hakkındaki tahminleri'], 'Model, tanığın uyarılmayı azaltmak için yardım etmenin ve etmemenin maliyet ve ödüllerini tarttığını öne sürer.'),
  ('Stanley Milgram\'ın \'kentsel aşırı yükleme\' hipotezi, kentlerde yaşayanların kırsal bölgelerde yaşayanlara göre yabancılara daha az yardım etmesini nasıl açıklar?', 'Kentteki aşırı uyaranlardan korunmak için insanların çevrelerine daha az dikkat etmesiyle', ['Kentlilerin doğuştan daha bencil olmasıyla', 'Kentlerde hiç acil durum yaşanmamasıyla', 'Kentlilerin yardım etmeyi yasaklayan kurallara uymak zorunda olmasıyla'], 'Milgram\'a göre kent yaşamının uyaran bombardımanı insanları seçici davranmaya ve çevredeki birçok olaya ilgisiz kalmaya iter.'),
  ('Daniel Batson\'un empati-özgecilik hipotezine göre gerçek anlamda özgecil yardımın kaynağı hangisidir?', 'İhtiyaç sahibinin yerine kendini koyup onun için kaygılanmak', ['Yardım edince ödül alma beklentisi', 'Başkalarının onayını kazanma isteği', 'Yardım etmediğinde suçluluk duyma korkusu ve toplumsal ayıplanmadan kaçma isteği'], 'Batson\'a göre empati duyulan kişiye yapılan yardım kendi çıkarı için değil, öncelikle onun iyiliği için yapılır.'),
  ('Batson\'un deneylerinde, empatisi yüksek katılımcılar \'kolay kaçış\' koşulunda, yani yardım etmeden kolayca ortamdan ayrılabildiklerinde bile yardım etmeyi seçmiştir. Bu bulgu neyi desteklemektedir?', 'Yardımın kendi rahatsızlığını azaltma güdüsünden bağımsız olabileceğini', ['Bütün yardımların bencil olduğunu', 'Empatinin yardımı azalttığını', 'Kolay kaçış olduğunda kimsenin yardım etmediğini ve empatinin hiçbir rolü olmadığını'], 'Kendi sıkıntısından kurtulmak isteyen biri kaçmayı seçerdi; empatisi yüksek olanların yine yardım etmesi özgecil bir güdüye işaret eder.'),
  ('Sosyal mübadele kuramına göre insanlar neden yardım eder?', 'Yardımın sağlayacağı ödüllerin maliyetlerinden fazla olduğunu hesapladıkları için', ['Yalnızca genetik akrabalarını korumak için', 'Yalnızca dinî bir zorunluluk olduğu için', 'Yardım etmenin hiçbir maliyeti olmadığı ve bunu her zaman bildikleri için'], 'Sosyal mübadele kuramı, yardımı kişinin ödül ve maliyetleri en iyi duruma getirme çabası olarak açıklar; ödüller onay ya da iyi hissetme gibi içsel olabilir.'),
  ('Robert Trivers\'in \'karşılıklı özgecilik\' kavramı neyi açıklar?', 'Akraba olmayanlara, ileride karşılık bekleyerek yardım etmeyi', ['Yalnızca çocuklara yapılan yardımı', 'Yardımın her zaman zararlı olduğunu', 'Yardımın hiç karşılık beklenmeden yalnızca bir kez yapılmasını ve sonra unutulmasını'], 'Karşılıklı özgecilik, bugün yapılan yardımın ileride karşılık görme olasılığı nedeniyle akraba olmayanlar arasında da evrimsel olarak avantajlı olabileceğini öne sürer.'),
  ('Elaine Walster ve arkadaşlarının 1966\'da üniversite öğrencileri için düzenlediği \'bilgisayar dansı\' çalışmasında, rastgele eşleştirilen çiftlerin birbirini yeniden görmek isteyip istemediğini en iyi yordayan etken hangisi olmuştur?', 'Partnerin fiziksel çekiciliği', ['Kişilik testlerindeki benzerlik', 'Zekâ puanlarının yakınlığı', 'Ailelerin sosyoekonomik düzeyleri ve yaşadıkları semtler'], 'Öğrencilerin flörtünü sürdürme isteğini kişilik ya da zekâdan çok, partnerin fiziksel çekiciliği belirlemiştir.'),
  ('Dion, Berscheid ve Walster\'ın 1972 çalışmasında katılımcıların fotoğraftaki çekici kişileri daha mutlu, daha başarılı ve daha iyi kişilikli olarak değerlendirmesi hangi kalıp yargıyı yansıtır?', '\'Güzel olan iyidir\' kalıp yargısı', ['\'Zıt kutuplar birbirini çeker\' inancı', '\'Gözden ırak olan gönülden de ırak olur\' inancı', 'Benzerlik-çekim ilkesi'], 'Fiziksel çekicilik, kişinin başka olumlu özelliklere de sahip olduğu çıkarımını doğurur; bu, hale etkisinin çekicilikteki biçimidir.'),
  ('Kişilerarası çekimde \'tamamlayıcılık\' görüşü \'zıt kutuplar birbirini çeker\' der. Araştırma bulguları bu görüş için genel olarak ne söyler?', 'Benzerlik, tamamlayıcılıktan çok daha güçlü bir çekim etkenidir', ['Zıtlık her zaman benzerlikten daha güçlü çekim yaratır', 'Benzerlik ve zıtlığın çekim üzerinde hiçbir etkisi yoktur', 'Tamamlayıcılık yalnızca yakın arkadaşlıklarda çekimi belirleyen tek etkendir'], 'Araştırmalar benzer tutum, değer ve ilgilerin çekimi güçlü biçimde artırdığını; zıtlıkların ise bu kadar tutarlı bir etkisi olmadığını göstermektedir.'),
  ('Dutton ve Aron\'un 1974 \'köprü deneyinde\' sallanan yüksek bir asma köprüden geçen erkekler, köprünün ortasında karşılaştıkları kadın araştırmacıyı sonradan daha sık aramıştır. Bunun açıklaması hangisidir?', 'Korkudan kaynaklanan uyarılmayı kadına duyulan çekime yüklemeleri', ['Köprünün manzarasının çok güzel olması', 'Kadının alçak köprüde daha az çekici görünmesi', 'Erkeklerin köprüden geçerken kadını tanımaları ve onunla önceden arkadaş olmaları'], 'Bu deney uyarılmanın yanlış atfını göstermiştir: Köprünün yarattığı fizyolojik uyarılma yanlışlıkla romantik çekim olarak yorumlanmıştır.'),
  ('Sternberg\'in kuramında tanışmadan kısa süre sonra tutku ve bağlılıkla hızla evlenen, ancak birbirini yeterince tanımayan bir çiftin aşkı hangi türe girer?', 'Kör (aptalca) aşk', ['Arkadaşça aşk', 'Romantik aşk', 'Boş aşk'], 'Tutku ve bağlılığın yakınlık olmadan birleşmesi kör aşkı oluşturur; bu tür ilişkiler sağlam bir duygusal temelden yoksundur.'),
  ('Elaine Hatfield\'in ayrımına göre \'tutkulu aşk\' ile \'arkadaşça aşk\' arasındaki temel fark hangisidir?', 'Tutkulu aşk yoğun özlem ve uyarılma içerir; arkadaşça aşk derin güven ve şefkate dayanır', ['Tutkulu aşk yalnızca yaşlılarda, arkadaşça aşk yalnızca gençlerde görülür', 'Tutkulu aşk hep ömür boyu sürer, arkadaşça aşk birkaç günde biter', 'İkisi arasında hiçbir fark yoktur; aynı duygunun farklı adlarıdır'], 'Tutkulu aşk genellikle ilişkinin başında yoğundur; arkadaşça aşk ise zamanla gelişen, hayatları birbirine bağlı kişiler arasındaki derin sevgidir.'),
  ('Thibaut ve Kelley\'nin sosyal mübadele kuramındaki \'karşılaştırma düzeyi\' kavramı neyi ifade eder?', 'Kişinin bir ilişkiden ne kadar ödül alacağına dair beklenti düzeyini', ['Partnerin fiziksel çekicilik puanını', 'İlişkinin kaç yıl sürdüğünü', 'Kişinin başka ilişkilerden ne kadar ödül alabileceğine dair beklentisi ve alternatiflerin değerlendirilmesi'], 'Karşılaştırma düzeyi, geçmiş deneyimlere dayanarak kişinin bir ilişkiden hak ettiğini düşündüğü sonuçların ölçüsüdür; ilişki doyumunu belirler.'),
  ('Caryl Rusbult\'un yatırım modeline göre bir ilişkiye bağlılığı belirleyen üç etken hangileridir?', 'Doyum, alternatiflerin niteliği ve yapılan yatırımlar', ['Yaş, gelir ve eğitim düzeyi', 'Fiziksel çekicilik, zekâ ve mizah', 'Benzerlik, yakınlık ve salt maruz kalma etkisinin süresi'], 'Yatırım modeline göre doyum yüksek, alternatifler zayıf ve yatırımlar (zaman, ortak arkadaşlar, ortak mal) büyük olduğunda bağlılık artar.'),
  ('Eşitlik kuramına göre bir ilişkide en çok doyum hangi durumda yaşanır?', 'Taraflardan her birinin aldığı ile verdiği arasındaki oranın dengeli olduğu durumda', ['Kişinin hiç vermeden çok aldığı durumda', 'Kişinin çok verip hiç almadığı durumda', 'Taraflardan birinin bütün kararları tek başına verdiği ve diğerinin yalnızca uyduğu durumda'], 'Eşitlik kuramına göre fazla alan taraf suçluluk, az alan taraf ise öfke duyar; dengeli ilişkiler en doyurucudur.'),
  ('Hazan ve Shaver\'ın 1987 araştırması, Ainsworth\'un bebeklikteki bağlanma stillerini hangi alana uygulamıştır?', 'Yetişkinlerin romantik ilişkilerine', ['Çocukların okul başarısına', 'Yaşlıların bellek sorunlarına', 'Hayvanların sürü davranışlarına ve göç yollarına'], 'Hazan ve Shaver, yetişkinlerin romantik ilişkilerinde de güvenli, kaçıngan ve kaygılı-kararsız bağlanma stillerinin görüldüğünü göstermiştir.'),
  ('Gottman\'ın \'duvar örme\' olarak adlandırdığı tutum hangisidir?', 'Tartışma sırasında partnere yanıt vermeyip iletişimi kesmek', ['Partneri sürekli övmek', 'Ortak bir hobi edinmek', 'Anlaşmazlığı uzlaşmaya varıncaya kadar sakin biçimde konuşup çözmeye çalışmak'], 'Duvar örme, kişinin tartışmadan duygusal olarak çekilip susması ve partnerini yok saymasıdır; ilişkiye zarar veren dört atlıdan biridir.'),
  ('Altman ve Taylor\'ın sosyal nüfuz etme kuramı, ilişkilerin gelişimini bir soğanın katmanlarına benzeterek neyi anlatır?', 'Kendini açmanın zamanla hem genişleyip hem derinleştiğini', ['İlişkilerin hiç değişmediğini', 'İnsanların en özel bilgilerini ilk gün paylaştığını', 'İlişkilerin hep yüzeysel kaldığını ve kişisel bilgilerin asla paylaşılmadığını'], 'Kurama göre başlangıçta yüzeysel ve az sayıda konu paylaşılır; ilişki ilerledikçe daha çok konu (genişlik) ve daha kişisel bilgiler (derinlik) açılır.'),
  ('Yeni tanıştığı birine ilk konuşmada en derin sırlarını anlatan birinin genellikle nasıl algılandığı bulunmuştur?', 'Uygunsuz biçimde fazla açılan ve daha az sevilen biri olarak', ['Çok güvenilir ve hemen sevilen biri olarak', 'İçe kapanık ve gizemli biri olarak', 'Sosyal becerileri çok gelişmiş ve herkesin hemen arkadaş olmak istediği biri olarak'], 'Kendini açmanın ilişkinin evresine uygun ve karşılıklı olması beklenir; çok erken derin açılma tuhaf ve rahatsız edici bulunur.'),
  ('Stanley Schachter\'ın 1959 deneyinde yakında acı verici şoklar alacakları söylenen kadın katılımcılar, beklerken nasıl bir tercihte bulunmuştur?', 'Aynı durumu yaşayan başka katılımcılarla birlikte beklemeyi', ['Tek başına beklemeyi', 'Deneyden hemen ayrılmayı', 'Hiç tanımadıkları ve deneye katılmayan kişilerle birlikte beklemeyi ve sohbet etmeyi'], 'Kaygısı yüksek katılımcılar birlikte beklemeyi tercih etmiş, özellikle de aynı durumdaki kişilerle birlikte olmak istemiştir; bu, kaygının birliktelik arayışını artırdığını gösterir.'),
  ('Roy Baumeister ve Mark Leary\'nin 1995\'te öne sürdüğü \'ait olma ihtiyacı\' kavramına göre bu ihtiyaç hangi niteliktedir?', 'İnsanlar için temel ve evrensel bir güdü', ['Yalnızca bazı kültürlerde görülen ve öğrenilen bir alışkanlık', 'Yalnızca çocuklukta görülüp sonra kaybolan bir istek', 'Yalnızca dışadönük kişilerde bulunan, içedönüklerde hiç görülmeyen bir özellik'], 'Baumeister ve Leary\'ye göre insanlar kalıcı, olumlu ve anlamlı ilişkiler kurmaya yönelik güçlü ve evrensel bir ihtiyaç taşır; bu ihtiyaç karşılanmadığında ruh sağlığı bozulur.'),
  ('Kipling Williams\'ın \'Cyberball\' adlı bilgisayar oyunuyla yaptığı deneylerde, sanal top atma oyununda topu kendilerine hiç atılmayan katılımcıların yaşadıkları hangisidir?', 'Kısa süreli bir dışlanmanın bile öz saygı ve ait olma duygusunu zedelemesi', ['Oyunun sanal olması nedeniyle hiçbir şey hissetmemeleri', 'Çok mutlu ve rahatlamış hissetmeleri', 'Oyunun kurallarını unutup ekrandaki topun rengini hatırlayamamaları'], 'Yabancılarla oynanan birkaç dakikalık sanal oyunda bile dışlanmak ait olma, öz saygı, denetim ve anlamlı varoluş ihtiyaçlarını tehdit etmiştir.'),
  ('Yalnızlık kavramının sosyal psikolojideki tanımına göre, çok sayıda arkadaşı olan bir kişinin yalnızlık hissetmesi mümkün müdür?', 'Evet; yalnızlık istenen ile var olan ilişkiler arasındaki farkın öznel algısıdır', ['Hayır; yalnızlık yalnızca hiç arkadaşı olmayanlarda görülür', 'Hayır; arkadaş sayısı arttıkça yalnızlık her zaman sıfırlanır', 'Evet; ancak yalnızca çok kalabalık şehirlerde yaşayan ve dışadönük olan kişilerde'], 'Yalnızlık nesnel ilişki sayısından çok, kişinin ilişkilerinin niceliği ya da niteliğinden duyduğu doyumsuzlukla ilgilidir.'),
  ('Antropolog Edward T. Hall\'un yakın alan bilimi (proksemik) çalışmalarına göre ABD\'de genellikle 0-45 cm arasındaki uzaklık hangi tür ilişkilere ayrılmıştır?', 'Mahrem (yakın) ilişkilere', ['Resmi iş görüşmelerine', 'Topluluk önünde konuşmalara', 'Tanımadığımız kişilerle yapılan kısa ve resmi alışveriş konuşmalarına'], 'Hall\'a göre mahrem alan sevgililer, aile üyeleri ve çok yakın arkadaşlar içindir; bu alana yabancıların girmesi rahatsızlık yaratır.'),
  ('Sözel olmayan iletişimde, bir kişinin söyledikleri ile ses tonu ve yüz ifadesi çeliştiğinde insanların genellikle hangisine daha çok güvendiği bulunmuştur?', 'Ses tonu ve yüz ifadesi gibi sözel olmayan ipuçlarına', ['Yalnızca söylenen sözcüklerin anlamına', 'Kişinin giydiği kıyafetin rengine', 'Konuşmanın yapıldığı odanın büyüklüğüne ve dekorasyonuna'], 'Sözel olmayan ipuçları daha az denetlenebildiği için insanlar çelişki durumunda gerçek duyguyu bunlardan çıkarmaya çalışır.'),
  ('Paul Ekman\'ın kavramlaştırdığı \'gösterme kuralları\' neyi ifade eder?', 'Bir kültürde hangi duygunun ne zaman ve ne ölçüde gösterilmesinin uygun olduğuna dair normları', ['Yüz ifadelerinin bütün kültürlerde tamamen farklı olduğunu', 'Duyguların hiçbir zaman gizlenemediğini', 'Yalnızca oyuncuların sahnede uyması gereken teknik kuralları ve kostüm seçimlerini'], 'Temel duygu ifadeleri evrensel olsa da kültürler bu ifadelerin hangi durumlarda gösterilip bastırılacağını farklı biçimde düzenler.'),
  ('Hazel Markus ve Shinobu Kitayama\'nın 1991\'de tanımladığı \'karşılıklı bağımlı benlik\' kurgusu hangi tür kültürlerde daha yaygındır?', 'Doğu Asya gibi toplulukçu kültürlerde', ['Kuzey Amerika gibi bireyci kültürlerde', 'Yalnızca göçebe toplumlarda', 'Yalnızca sanayileşmiş Batı Avrupa ülkelerinin büyük kentlerinde'], 'Karşılıklı bağımlı benlikte kişi kendini ilişkileri ve rolleri üzerinden tanımlar; bağımsız benlikte ise kişisel özellikleri ve özerkliği öne çıkar.'),
  ('Çiğdem Kağıtçıbaşı\'nın \'özerk-ilişkisel benlik\' kavramı, Batı psikolojisindeki hangi varsayıma itiraz eder?', 'Özerklik ile ilişkiselliğin birbirinin karşıtı olduğu varsayımına', ['İnsanların grup içinde yaşadığı varsayımına', 'Ailenin toplumsallaşmadaki rolü varsayımına', 'Çocukların ebeveynlerinden etkilendiği ve onları taklit ettiği varsayımına'], 'Kağıtçıbaşı, bireyin hem özerk hem de başkalarıyla yakından bağlı olabileceğini, bu iki ihtiyacın birbirini dışlamadığını savunmuştur.'),
  ('Michele Gelfand\'ın \'sıkı ve gevşek kültürler\' ayrımı neye dayanır?', 'Toplumsal normların gücüne ve normlardan sapmaya gösterilen hoşgörü düzeyine', ['Toplumların nüfus yoğunluğuna', 'Ülkelerin iklim kuşaklarına', 'Toplumların resmi dillerinin sayısına ve alfabelerinin türüne'], 'Sıkı kültürlerde normlar güçlüdür ve sapmalar sert yaptırımla karşılanır; gevşek kültürlerde ise normlar esnektir ve sapmaya daha hoşgörülü yaklaşılır.'),
  ('Ed Diener ve arkadaşlarının Cadılar Bayramı\'nda yaptığı çalışmada, hangi koşuldaki çocukların izin verilenden fazla şeker ve para alma olasılığının en yüksek olduğu bulunmuştur?', 'Grup halinde gelen ve adı sorulmayan çocukların', ['Tek başına gelen ve adı sorulan çocukların', 'Ebeveyniyle gelen çocukların', 'Kostüm giymeyen ve ev sahibiyle uzun süre sohbet eden çocukların'], 'Grup içinde olma ve kimliğin bilinmemesi birleştiğinde kural ihlali en yüksek düzeye çıkmış; bu, bireysizleşmenin koşullarını göstermiştir.'),
  ('Reicher ve Spears\'ın sosyal kimlik modeline (SIDE) göre bireysizleşme her zaman saldırganlığa yol açmaz. Kimliksizleşen bir kişinin davranışını ne belirler?', 'O anda belirgin olan grup kimliğinin normları', ['Kişinin yalnızca kalıtsal özellikleri', 'Kişinin o günkü hava durumu algısı', 'Kişinin en son izlediği filmdeki karakterin davranışları ve sözleri'], 'SIDE modeline göre bireysel kimlik silindiğinde grup kimliği belirginleşir ve kişi o grubun normlarına, olumlu ya da olumsuz olsun, daha çok uyar.'),
  ('Greenberg, Solomon ve Pyszczynski\'nin dehşet yönetimi kuramına göre insanlar ölümün kaçınılmazlığından doğan kaygıyla nasıl başa çıkar?', 'Kültürel dünya görüşlerine sarılıp öz saygılarını güçlendirerek', ['Ölümü düşünmeyi tamamen öğrenerek unutarak', 'Bütün kültürel değerleri reddederek', 'Yalnızca fiziksel egzersiz yaparak ve beslenmelerini değiştirerek'], 'Kurama göre kültürel dünya görüşü ve bu görüşe göre değerli olma duygusu, ölüm kaygısına karşı psikolojik bir tampon görevi görür.'),
  ('John Jost\'un sistemi meşrulaştırma kuramına göre, dezavantajlı grupların üyelerinin bazen kendilerini dezavantajlı kılan toplumsal düzeni savunmasının nedeni hangisidir?', 'Mevcut sistemi adil ve meşru görme yönündeki güdü', ['Sistemin onlara her zaman en çok yararı sağlaması', 'Sistem hakkında hiçbir bilgilerinin olmaması', 'Sistemi değiştirmenin yasal olarak tamamen yasaklanmış olması ve buna karşı cezaların bulunması'], 'Jost\'a göre insanlar belirsizlik ve tehdidi azaltmak için içinde yaşadıkları düzeni adil görme eğilimindedir; bu eğilim dezavantajlı gruplarda bile görülebilir.'),
  ('Stanley Milgram\'ın 1967\'de Nebraska ve Kansas\'tan seçilen kişilerden Boston\'daki bir hedef kişiye yalnızca tanıdıkları aracılığıyla mektup ulaştırmalarını istediği çalışma hangi kavramı doğurmuştur?', 'Küçük dünya olgusu ve \'altı derece ayrılık\'', ['Kentsel aşırı yükleme', 'Ajantik durum', 'Uyarılma aktarımı ve onun ilişkilere etkisi'], 'Hedefe ulaşan mektuplar ortalama beş-altı aracıdan geçmiş; bu da birbirini tanımayan insanların kısa tanıdık zincirleriyle bağlı olduğunu düşündürmüştür.'),
  ('Milgram\'ın geliştirdiği \'kayıp mektup tekniği\'nde, farklı kuruluşlara adreslenmiş pullu mektuplar sokaklara bırakılır. Bu teknik neyi ölçmek için kullanılır?', 'Bir topluluğun farklı gruplara yönelik tutumlarını dolaylı olarak', ['Postanelerin çalışma hızını', 'İnsanların el yazısını okuma becerisini', 'Kentteki trafik yoğunluğunu ve yayaların yürüme hızını'], 'Bulan kişilerin hangi kuruluşa adreslenmiş mektupları postaya attığı, o kuruluşlara yönelik tutumların tepkisiz (dolaylı) bir ölçüsü olarak kullanılır.'),
  ('Milgram\'ın \'tanıdık yabancı\' kavramı neyi anlatır?', 'Her gün aynı yerde görülen ama hiç konuşulmayan kişileri', ['Çocukluk arkadaşlarını', 'Uzaktan tanınan ünlüleri', 'Sosyal medyada takip edilen ama gerçek hayatta hiç görülmemiş olan ve başka ülkelerde yaşayan kişileri'], 'Örneğin her sabah aynı durakta beklenen ama hiç konuşulmayan kişiler tanıdık yabancılardır; Milgram bunları kent yaşamının özgün bir ilişki biçimi olarak incelemiştir.'),
  ('Muzafer Şerif ile Carl Hovland\'ın geliştirdiği sosyal yargı kuramına göre bir ikna mesajı, kişinin hangi alanına düştüğünde en çok tutum değişikliği yaratır?', 'Kabul alanının sınırına yakın, ama içinde kalan konuma', ['Ret alanının tam ortasına', 'Kişinin mevcut tutumuyla tamamen aynı noktaya', 'Kişinin hiç ilgilenmediği bir konuya ait olan ve ret alanının en uç noktasındaki konuma'], 'Kurama göre mesaj kabul alanında kalırsa tutum ona doğru kayar (özümleme); ret alanına düşerse olduğundan da uzak algılanır (karşıtlık) ve değişim olmaz.'),
  ('Sosyal yargı kuramındaki \'karşıtlık etkisi\' neyi anlatır?', 'Ret alanındaki bir görüşün olduğundan daha uç ve uzak algılanmasını', ['Kabul alanındaki görüşlerin olduğundan daha uzak algılanmasını', 'İki karşıt görüşün aynı anda kabul edilmesini', 'Kişinin karşıt görüşü duyunca hemen kendi görüşünü değiştirip ona katılmasını'], 'Ret alanına düşen mesajlar kişinin kendi tutumundan olduğundan daha uzak algılanır; kabul alanındakiler ise daha yakın algılanır (özümleme etkisi).'),
  ('Benjamin Franklin\'in, kendisine karşı soğuk davranan bir rakibinden nadir bir kitabı ödünç isteyip sonra onunla dost olduğunu anlattığı öykü, sosyal psikolojide hangi olguya ad vermiştir?', 'Birine iyilik yapanın ondan daha çok hoşlanması', ['İyilik görenin iyilik yapanı daha az sevmesi', 'Rakiplerin hiçbir zaman dost olamaması', 'Ödünç verilen eşyaların zamanla daha değerli hale gelmesi ve bunun alıcıyı memnun etmesi'], 'Ben Franklin etkisi bilişsel çelişkiyle açıklanır: Kişi sevmediği birine yaptığı iyiliği \'Demek ki ondan hoşlanıyorum\' diyerek gerekçelendirir.'),
  ('Claude Steele\'in öz onaylama kuramına göre, bir çelişki yaşayan kişinin kendi önemli değerlerinden birini, örneğin ailesine verdiği değeri düşünüp yazması ne sonuç doğurur?', 'Çelişkiyi azaltmak için tutumunu değiştirme gereksinimini azaltır', ['Çelişkiyi artırıp tutum değişimini hızlandırır', 'Kişinin bütün değerlerini sorgulamasına yol açar', 'Kişinin öz saygısını düşürüp çelişkiyi daha da büyütür ve onu çaresiz bırakır'], 'Öz onaylama, benliğin genel bütünlüğünü güçlendirerek tehdidi hafifletir; böylece kişi tutarsızlığı savunmacı biçimde gidermek zorunda kalmaz.'),
  ('William Swann\'ın kendini doğrulama kuramına göre olumsuz bir benlik görüşüne sahip kişiler hangi tür geri bildirimi tercih edebilir?', 'Kendi olumsuz görüşlerini doğrulayan geri bildirimi', ['Her durumda yalnızca abartılı övgüyü', 'Hiçbir geri bildirimi', 'Kendileriyle hiç ilgisi olmayan ve rastgele verilen geri bildirimleri'], 'Kendini doğrulama kuramına göre insanlar benlik görüşlerinin tutarlılığını korumak ister; bu yüzden olumsuz benlik görüşündekiler bile onları doğrulayan partnerleri tercih edebilir.'),
  ('Mark Leary\'nin sosyometre kuramına göre öz saygı neyin göstergesi olarak işlev görür?', 'Kişinin başkalarınca ne ölçüde kabul gördüğünün', ['Kişinin zekâ düzeyinin', 'Kişinin fiziksel sağlığının', 'Kişinin ekonomik gelirinin ve sahip olduğu malların toplam değerinin'], 'Sosyometre kuramına göre öz saygı, sosyal kabul ve dışlanmayı izleyen içsel bir gösterge gibidir; dışlanma öz saygıyı düşürür.'),
  ('Neil Weinstein\'ın 1980 çalışmasında üniversite öğrencilerinin, iyi bir iş bulma gibi olumlu olayların kendi başlarına başkalarından daha çok, ciddi hastalık gibi olumsuz olayların ise daha az geleceğini düşünmesi hangi yanılgıdır?', 'Gerçekçi olmayan iyimserlik', ['Öğrenilmiş çaresizlik', 'Savunmacı karamsarlık', 'Yanlış uzlaşma etkisi ve yaygınlık sanısı'], 'Gerçekçi olmayan iyimserlik, kişinin kendi geleceğini başkalarınınkinden sistematik olarak daha olumlu görmesidir; sağlık önlemlerini ihmal etmeye yol açabilir.'),
  ('Önemli bir sınavdan önce \'Kesin kötü geçecek\' diye düşünen, ancak bu kaygıyı daha çok çalışmak için kullanan öğrencilerin stratejisine ne ad verilir?', 'Savunmacı karamsarlık', ['Kendini engelleme', 'Gerçekçi olmayan iyimserlik', 'Öğrenilmiş çaresizlik ve tamamen pes etme'], 'Julie Norem\'in tanımladığı savunmacı karamsarlıkta kişi olası kötü sonuçları önceden düşünerek kaygısını yönetir ve hazırlığını artırır.'),
  ('Gilbert ve Wilson\'ın \'duygusal tahmin\' araştırmalarına göre insanlar bir piyango kazanmanın ya da bir ilişkinin bitmesinin kendilerini ne kadar süre etkileyeceğini nasıl tahmin eder?', 'Olayın duygusal etkisinin süresini ve şiddetini abartarak', ['Olayın etkisini tamamen doğru tahmin ederek', 'Olayların hiç etkilemeyeceğini sanarak', 'Olumlu olayların etkisini küçümseyip yalnızca olumsuzları abartarak'], 'Etki yanlılığı denilen bu eğilimde insanlar psikolojik bağışıklık sistemlerinin olumsuz olayların etkisini ne kadar hızlı hafifleteceğini göz ardı eder.'),
  ('Marilynn Brewer\'ın en uygun ayırt edicilik kuramına göre insanlar hangi iki güdü arasında denge arar?', 'Bir gruba ait olma ve diğerlerinden farklı olma', ['Para kazanma ve harcama', 'Uyuma ve uyanık kalma', 'Başkalarına saldırma ve onlardan kaçma ile kendini koruma'], 'Brewer\'a göre insanlar hem dahil olma hem de ayrışma gereksinimi duyar; bu nedenle ne çok büyük ne çok küçük, orta büyüklükteki gruplarla daha güçlü özdeşleşir.'),
  ('Marques ve arkadaşlarının \'kara koyun etkisi\' kavramı neyi anlatır?', 'Kötü davranan iç grup üyesinin, aynı davranıştaki dış grup üyesinden daha sert yargılanmasını', ['İç grup üyelerinin her zaman olumlu değerlendirilmesini', 'Dış grup üyelerinin her zaman daha sert yargılanmasını', 'Gruptan ayrılan üyelerin hemen unutulmasını ve onlardan hiç söz edilmemesini'], 'İç grubun olumlu imajını tehdit eden kendi üyeler, grubun kimliğini korumak için dış grup üyelerinden daha olumsuz değerlendirilebilir.'),
  ('Bir kişinin, kendisini değerli hissettiği bir alanda başarısız olduktan sonra o alanın kendisi için önemli olmadığını söylemesi Tesser\'in modeline göre hangi stratejidir?', 'Alanın kişisel önemini azaltmak', ['Yakın arkadaşla bağı güçlendirmek', 'Başarıyı başkasına yansıtmak', 'Başarısızlığı daha önemli bir alana taşıyıp orada yarışmaya karar vermek'], 'Tesser\'in modelinde benlik değerlendirmesi tehdit edildiğinde kişi alanın önemini düşürebilir, karşılaştırılan kişiyle mesafesini artırabilir ya da performansı değiştirmeye çalışabilir.'),
  ('Lee Ross\'un \'saf gerçekçilik\' kavramına göre insanlar kendi görüşleri ile kendilerinden farklı düşünenler hakkında ne varsayar?', 'Kendilerinin dünyayı olduğu gibi gördüğünü, farklı düşünenlerin ise bilgisiz ya da taraflı olduğunu', ['Herkesin aynı derecede taraflı olduğunu', 'Kendi görüşlerinin her zaman yanlış olduğunu', 'Farklı düşünenlerin her zaman daha bilgili ve daha nesnel olduğunu, kendilerinin ise yanıldığını'], 'Saf gerçekçilik, kişinin kendi algısını nesnel gerçeklik sanması ve buna uymayanları önyargılı ya da yanlış bilgilendirilmiş görmesidir.'),
  ('Emily Pronin ve arkadaşlarının \'yanlılık kör noktası\' kavramı neyi anlatır?', 'İnsanların başkalarındaki yanlılıkları kendilerindekinden daha kolay fark etmesini', ['İnsanların hiç yanlılığı olmamasını', 'İnsanların kendi yanlılıklarını başkalarınınkinden daha iyi görmesini', 'Gözün görme alanında bulunan ve ışığa duyarlı olmayan bölgeyi'], 'İnsanlar başkalarının yargılarının önyargılarla çarpıtıldığını kolayca kabul eder, ama kendilerini bu yanlılıklardan görece özgür sanır.'),
  ('Bir iddianın doğru olup olmadığına bakılmaksızın, yalnızca tekrar tekrar duyulmasının onu daha inandırıcı hale getirmesine ne ad verilir?', 'Yanılsamalı doğruluk etkisi', ['Uyuyan etki', 'Tepkisellik', 'Aşılama etkisi ve önceden direnç kazanma'], 'Hasher ve arkadaşlarının 1977\'de gösterdiği bu etki, tekrarlanan ifadelerin daha kolay işlenmesi ve tanıdık gelmesi nedeniyle doğru sanılmasıdır.'),
  ('Shelly Chaiken\'in sezgisel-sistematik ikna modeli ile Ayrıntılandırma Olasılığı Modeli\'nin ortak noktası hangisidir?', 'İknanın dikkatli düşünme ve kestirme ipuçları olmak üzere iki yolla gerçekleşebileceği', ['İknanın yalnızca korkuyla gerçekleştiği', 'İknanın yalnızca kaynağın çekiciliğine bağlı olduğu', 'İnsanların her mesajı her zaman ayrıntılı ve titizlikle değerlendirdiği, kestirme yol kullanmadığı'], 'Her iki model de ikili süreç modelidir: Biri mesaj içeriğinin dikkatle işlenmesine, diğeri \'Uzmanlar genelde haklıdır\' gibi kestirmelere dayanır.'),
  ('Bir münazarada iki konuşma arka arkaya yapılıp karar ancak bir hafta sonra verilecekse, Miller ve Campbell\'ın 1959 bulgularına göre hangi konuşmacı avantajlıdır?', 'İlk konuşan', ['Son konuşan', 'İkisi arasında hiçbir fark yoktur', 'Hangi konuşmacının daha uzun konuştuğuna göre değişir ve sıra hiç önemli değildir'], 'İki mesaj arka arkaya verilip karar gecikirse ilk mesajın etkisi (öncelik) baskın çıkar; mesajlar arasında zaman var ve karar hemen veriliyorsa son mesaj (sonralık) avantajlıdır.'),
  ('Steiner\'e göre bir bilmece yarışmasında grubun, üyelerinden birinin doğru yanıtı bulmasıyla başarılı sayıldığı görev türü hangisidir?', 'Ayırıcı (disjunctive) görev', ['Bağlayıcı görev', 'Toplamsal görev', 'Karma (bölünebilir) görev ve iş paylaşımı'], 'Ayırıcı görevlerde grup performansı en yetenekli üyenin performansına bağlıdır.'),
  ('Köhler etkisi denilen olguda, bir grubun en zayıf üyesinin grup içinde tek başına çalıştığından daha fazla çaba göstermesinin nedeni hangisidir?', 'Grubun başarısının kendisine bağlı olduğunu hissetmesi', ['Grubun onu tamamen görmezden gelmesi', 'Görevin daha kolay hale gelmesi', 'Diğer üyelerin onun yerine çalışması ve onun yalnızca izlemesi'], 'Bağlayıcı görevlerde zayıf üye, grubun kendisi yüzünden başarısız olmasını istemediği için çabasını artırır; bu sosyal kaytarmanın tersidir.'),
  ('Uzun süredir evli bir çiftte eşlerden birinin telefon numaralarını, diğerinin ise doğum günlerini hatırlayıp birbirlerinin belleğine güvenmesi Daniel Wegner\'in hangi kavramına örnektir?', 'Eylemsel (paylaşılan) bellek sistemi', ['Kendini engelleme', 'Grup düşüncesi', 'Sosyal kaytarma ve çaba azaltma'], 'Wegner\'e göre yakın gruplarda üyeler bilgileri bölüşerek bir tür ortak bellek sistemi oluşturur ve kimin neyi bildiğini bilir.'),
  ('Karau ve Williams\'ın \'kolektif çaba modeli\'ne göre sosyal kaytarma hangi durumlarda azalır?', 'Görev anlamlı olduğunda ve kişinin katkısı sonucu belirgin biçimde etkilediğinde', ['Grup çok büyük olduğunda', 'Katkılar hiç değerlendirilmediğinde', 'Üyeler birbirini hiç tanımadığında ve görev çok sıkıcı olduğunda'], 'Modele göre insanlar çabalarının değerli bir sonuca ulaşmada önemli olduğuna inandıklarında grup içinde de çabalarını sürdürür.'),
  ('Alice Eagly\'nin sosyal rol kuramına göre kadınlar ve erkekler arasındaki davranış farklılıklarının temel kaynağı hangisidir?', 'Toplumdaki iş bölümü ve bunun doğurduğu cinsiyet rolü beklentileri', ['Yalnızca hormon düzeylerindeki farklılıklar', 'Kadınların ve erkeklerin farklı gezegenlerden geldiği gibi doğuştan zihinsel yapılar', 'İklim ve coğrafyanın doğrudan etkisi ile beslenme biçimleri'], 'Sosyal rol kuramına göre kadın ve erkeklerin tarihsel olarak üstlendiği farklı roller, bu rollere uygun özelliklerin beklenmesine ve geliştirilmesine yol açar.'),
  ('Bond ve Smith\'in 1996\'da Asch türü çalışmaları birleştiren meta-analizi, uymanın hangi tür kültürlerde daha yüksek olduğunu göstermiştir?', 'Toplulukçu kültürlerde', ['Bireyci kültürlerde', 'Kültürden bağımsız olarak her yerde aynı düzeyde', 'Yalnızca Kuzey Avrupa ülkelerinde ve İskandinavya\'da'], 'Meta-analiz, uyum ve grup uyumunu önemseyen toplulukçu kültürlerde Asch türü görevlerde uyma oranlarının daha yüksek olduğunu bulmuştur; aynı çalışma ABD\'de uymanın 1950\'lerden beri azaldığını da göstermiştir.'),
  ('Perrin ve Spencer\'ın 1980\'de İngiltere\'de Asch deneyini tekrarladıklarında mühendislik öğrencileriyle çok düşük uyma bulmaları, Asch\'in bulguları hakkında hangi yoruma yol açmıştır?', 'Uyma oranlarının dönemin ve kültürün koşullarına bağlı olabileceği', ['Asch\'in deneyinin hiç yapılmadığı', 'Uymanın her dönemde tamamen sabit kaldığı', 'Mühendislerin görme yeteneğinin herkesten üstün olduğu ve çizgileri daha iyi gördüğü'], 'Perrin ve Spencer, Asch\'in bulgularını 1950\'lerin ABD\'sindeki baskıcı iklimin bir ürünü (\'dönemin çocuğu\') olarak yorumlamıştır.'),
  ('Manning, Levine ve Collins\'in 2007 incelemesi, Kitty Genovese olayına ilişkin yaygın anlatı hakkında neyi ortaya koymuştur?', '\'38 tanığın hiçbir şey yapmadan izlediği\' anlatısının abartılı olduğunu', ['Olayın hiç yaşanmadığını', 'Olayın 1990\'larda Londra\'da geçtiğini', 'Tanık sayısının aslında 380 olduğunu ve tamamının olayı baştan sona izlediğini'], 'İnceleme, tanıkların çoğunun saldırıyı tam olarak göremediğini, bazılarının polisi aradığını ve olayın medyada abartıldığını göstermiştir; ancak seyirci etkisi deneysel olarak ayrıca kanıtlanmıştır.'),
  ('Gaertner ve Dovidio\'nun \'kaçıngan ırkçılık\' kavramına göre eşitlikçi değerlere içtenlikle inanan kişiler ayrımcılığı hangi durumlarda daha çok gösterir?', 'Davranışın ırk dışında bir gerekçeyle açıklanabildiği belirsiz durumlarda', ['Ayrımcılığın açıkça fark edileceği durumlarda', 'Hiçbir durumda', 'Yalnızca yalnız olduklarında ve kimse onları izlemediğinde, hiçbir gerekçe yokken'], 'Kaçıngan ırkçılıkta önyargı, kişinin kendisini ve başkalarını ırkçı olmadığına inandırabileceği belirsiz durumlarda ortaya çıkar.'),
  ('Kalıp yargı içerik modeline göre, yaşlılar gibi \'sıcak ama yetersiz\' algılanan gruplara karşı genellikle hangi duygu beslenir?', 'Acıma', ['Kıskançlık', 'Hayranlık', 'Tiksinti ve küçümseme ile birlikte düşmanlık'], 'Modele göre sıcak-yetersiz gruplara acıma, soğuk-yetkin gruplara kıskançlık, sıcak-yetkin gruplara hayranlık, soğuk-yetersiz gruplara ise küçümseme duyulur.'),
  ('Kalıp yargı içerik modeline göre ekonomik olarak başarılı ama soğuk ve çıkarcı olarak algılanan bir azınlık grubuna yönelik baskın duygu hangisidir?', 'Kıskançlık', ['Acıma', 'Hayranlık', 'Şefkat ve koruma isteği'], 'Yetkin ama soğuk algılanan gruplar kıskançlık uyandırır; bu duygu kriz zamanlarında saldırgan tepkilere dönüşebilir.'),
  ('Lee\'nin aşk tarzları arasında, partnerini eğitim, gelir ve aile uyumu gibi ölçütlere göre bir alışveriş listesi gibi seçen kişinin tarzı hangisidir?', 'Pragma', ['Mania', 'Eros', 'Ludus'], 'Pragma, uygunluk ve pratik hesaplara dayanan akılcı bir aşk tarzıdır.'),
  ('\'Ultimatom oyunu\'nda bir oyuncu belli bir parayı diğeriyle nasıl paylaşacağını önerir; diğeri reddederse ikisi de hiçbir şey alamaz. Araştırmalarda yanıt verenlerin çok düşük teklifleri sıklıkla reddetmesi neyi gösterir?', 'İnsanların adaletsizliği cezalandırmak için kendi kazançlarından vazgeçebildiğini', ['İnsanların her zaman en yüksek parasal kazancı seçtiğini', 'Oyunun kurallarının anlaşılmadığını', 'Yanıt verenlerin paraya hiç ihtiyacı olmadığını ve oyunu ciddiye almadığını'], 'Salt ekonomik akılcılığa göre her pozitif teklif kabul edilmelidir; ancak insanlar adalet normlarını ihlal eden teklifleri reddederek karşı tarafı cezalandırır.'),
  ('Thibaut ve Walker\'ın \'usul adaleti\' kavramına göre insanlar bir kararı ne zaman daha adil bulur?', 'Karar sürecinde söz hakkı tanındığında ve süreç tarafsız işletildiğinde', ['Yalnızca kendi lehlerine sonuç çıktığında', 'Karar çok hızlı verildiğinde', 'Kararı veren kişi çok zengin olduğunda ve kendini kimseye açıklamak zorunda olmadığında'], 'Usul adaleti araştırmaları, sonuç olumsuz olsa bile adil ve saygılı bir sürecin kararların kabulünü artırdığını göstermiştir.'),
  ('Bir dış grubun üyelerinin tam insan sayılmaması, onlara yalnızca temel duyguların atfedilip \'özlem, utanç\' gibi daha insani duyguların yakıştırılmaması hangi kavramla incelenir?', 'İnsandışılaştırma', ['Sosyal yaratıcılık', 'Kalıp yargı tehdidi', 'Dış grup türdeşliği ve benzer görme'], 'Leyens ve arkadaşlarının araştırmaları, insanların dış gruplara insana özgü ikincil duyguları daha az atfettiğini göstermiştir; uç biçimi şiddeti meşrulaştırabilir.'),
  ('Sosyal psikolojide \'yoğunluk\' ile \'kalabalık hissi\' arasındaki ayrıma göre kalabalık hissi neyi ifade eder?', 'Kişinin ortamda kendini sıkışmış ve rahatsız hissetmesini', ['Belirli bir alandaki kişi sayısının nesnel ölçüsünü', 'Kentlerin nüfus artış hızını', 'Bir binanın kat sayısı ile metrekaresinin oranını ve yapı yoğunluğunu'], 'Yoğunluk metrekare başına düşen kişi sayısıdır; kalabalık hissi ise bu yoğunluğun kişi tarafından öznel olarak olumsuz algılanmasıdır.'),
  ('Sosyal desteğin \'tampon\' etkisi hipotezine göre güçlü sosyal ilişkilere sahip olmak sağlığı nasıl etkiler?', 'Yüksek stres dönemlerinde stresin olumsuz sağlık etkilerini hafifletir', ['Stresi her zaman artırır', 'Sağlık üzerinde hiçbir etkisi yoktur', 'Yalnızca stresin hiç olmadığı dönemlerde etkili olur, stres anında hiçbir işe yaramaz'], 'Cohen ve Wills\'in tampon hipotezine göre sosyal destek, özellikle stresli olaylar sırasında kişiyi bu olayların zararlı etkilerinden korur.'),
  ('Elaine Hatfield ve arkadaşlarının tanımladığı \'duygu bulaşması\' neyi anlatır?', 'İnsanların başkalarının duygularını kendiliğinden yakalayıp benzer duygular yaşamasını', ['Duyguların mikrop gibi hastalık yaymasını', 'İnsanların duygularını tamamen gizleyebilmesini', 'Bir kişinin başkalarının duygusunu bilinçli olarak tahmin edip not etmesini ve kaydetmesini'], 'Duygu bulaşmasında kişiler başkalarının yüz ifadesini, ses tonunu ve duruşunu farkında olmadan taklit eder ve bu taklit benzer duyguları doğurur.'),
  ('Fazio, Zanna ve Cooper\'ın 1977 çalışmasına göre, bilişsel çelişki kuramı ve öz algı kuramı hangi durumlara daha iyi uyar?', 'Çelişki kuramı tutuma çok aykırı davranışlara, öz algı kuramı ise tutuma yakın davranışlara', ['İki kuram da tamamen aynı durumları açıklar', 'Öz algı kuramı tutuma çok aykırı davranışlara, çelişki kuramı tutuma yakın davranışlara', 'İki kuram da tutum değişimini açıklayamaz ve ikisi de geçersiz sayılmıştır'], 'Kabul alanının dışındaki aykırı davranışlar rahatsızlık ve çelişki yaratır; kabul alanındaki hafif sapmalarda ise kişi tutumunu davranışından çıkarır.'),
  ('Bir araştırmacı, insanların gerçekten ne kadar yardımsever olduğunu öğrenmek için katılımcılara anket yerine sokakta düşürülmüş eldivenleri geri verip vermediklerini gözlemliyor. Bu yaklaşımın anket yöntemine göre avantajı hangisidir?', 'Sosyal beğenirlik etkisinin azalması', ['Katılımcı sayısının her zaman daha fazla olması', 'Katılımcıların araştırmayı bilmesi', 'Verilerin daha kolay ve hızlı çözümlenebilmesi, hiçbir yorum gerektirmemesi'], 'İnsanlar anketlerde kendilerini olduğundan iyi gösterebilir; doğal ortamda fark ettirmeden yapılan gözlemler bu çarpıtmayı azaltır.'),
  ('Sağlık kampanyalarında \'Güneş kremi kullanırsanız cildiniz genç kalır\' gibi kazanç vurgulu, \'Kullanmazsanız cilt kanseri riski artar\' gibi kayıp vurgulu mesajlar kullanılır. Araştırmalara göre önleyici davranışları teşvik etmede genellikle hangisi daha etkilidir?', 'Kazanç vurgulu mesajlar', ['Kayıp vurgulu mesajlar', 'İkisi arasında hiçbir zaman fark yoktur', 'Hiçbir mesaj içermeyen, yalnızca ürün resmi gösteren ve marka adını vurgulayan afişler'], 'Rothman ve Salovey\'e göre güneş kremi gibi önleyici davranışlarda kazanç, mamografi gibi hastalık saptayıcı davranışlarda ise kayıp vurgulu mesajlar daha etkilidir.'),
  ('Dürtme (nudge) yaklaşımına göre organ bağışını artırmak için en etkili yöntemlerden biri hangisidir?', 'Bağışçılığı varsayılan seçenek yapıp istemeyenin çıkmasına izin vermek', ['Bağışı yasal olarak zorunlu kılmak', 'Bağışçılara yüksek para ödülü vermek', 'Bağışçılık için çok sayıda belge isteyip süreci uzatmak ve zorlaştırmak'], 'Johnson ve Goldstein\'ın çalışmaları, bağışçılığın varsayılan olduğu ülkelerde bağış oranlarının, açıkça kayıt gerektiren ülkelere göre çok daha yüksek olduğunu göstermiştir.'),
  ('Hawthorne çalışmalarından sonra örgüt psikolojisinde \'insan ilişkileri\' yaklaşımının yükselmesi hangi bulguya dayanır?', 'Çalışanların verimliliğinde sosyal ilişkilerin ve ilginin önemli rol oynaması', ['Aydınlatma düzeyinin verimliliği tek başına belirlemesi', 'Ücret artışının verimliliği hiç etkilememesi', 'Çalışanların yalnızca ceza tehdidiyle verimli çalışması'], 'Western Electric fabrikasındaki çalışmalar, fiziksel koşullardan çok işçilere gösterilen ilginin ve grup normlarının verimliliği etkilediğini düşündürmüştür.'),
  ('Kurt Lewin\'in örgütsel ve toplumsal değişim için önerdiği üç aşamalı model hangi sırayla ilerler?', 'Çözme, değiştirme, yeniden dondurma', ['Değiştirme, çözme, yeniden dondurma', 'Dondurma, çözme, değiştirme', 'Planlama, uygulama, denetleme ve ardından ödüllendirme'], 'Lewin\'e göre önce mevcut alışkanlıklar \'çözülür\', sonra yeni davranışlara geçilir, en son bu yeni davranışlar kalıcı hale getirilir.'),
  ('Lewin\'in beslenme alışkanlıkları çalışmalarında ortaya attığı \'kapı bekçisi\' kavramı, ailede hangi yiyeceklerin sofraya geleceğine kimin karar verdiğini anlatır. Bu kavramın uygulamadaki önemi nedir?', 'Değişimi hedefleyen bir kampanyanın, kararı veren kişiye yönelmesi gerektiği', ['Kampanyaların yalnızca çocuklara yönelmesi gerektiği', 'Kapıların her zaman kapalı tutulması gerektiği', 'Yiyeceklerin fiyatının değişimde tek belirleyici olduğu ve başka hiçbir etkenin önemsiz kaldığı'], 'Lewin, bir kanaldan geçen şeyin kapı bekçisinin kararına bağlı olduğunu göstermiş; bu kavram sonradan iletişim ve medya çalışmalarında da kullanılmıştır.'),
  ('Serge Moscovici\'nin \'sosyal temsiller\' kuramı neyi inceler?', 'Bilimsel bilgilerin ve yeni fikirlerin gündelik sağduyu bilgisine nasıl dönüştüğünü', ['Bireylerin beyinlerindeki sinir hücrelerini', 'Siyasi partilerin seçim sonuçlarını', 'Kişinin yalnız başına nasıl düşündüğünü, toplumdan tamamen bağımsız olarak'], 'Moscovici, psikanalizin Fransız toplumunda nasıl yayılıp sağduyu bilgisine dönüştüğünü inceleyerek sosyal temsiller kuramını geliştirmiştir.'),
  ('Grup kutuplaşmasını açıklayan \'ikna edici argümanlar\' görüşüne göre tartışma sonrasında grubun daha uç bir noktaya kaymasının nedeni hangisidir?', 'Üyelerin başlangıç eğilimini destekleyen yeni argümanlar duyması', ['Üyelerin karşı görüşü destekleyen argümanları duyması', 'Grubun liderinin herkesi tehdit etmesi', 'Üyelerin tartışma sırasında hiç konuşmaması ve yalnızca oy vermesi'], 'Benzer görüşteki kişilerin tartışmasında çoğunlukla aynı yönde argümanlar dile getirilir; bu da herkesin görüşünü daha da güçlendirir.'),
  ('Grup kutuplaşmasının \'sosyal karşılaştırma\' açıklamasına göre üyeler tartışma sırasında neden daha uç görüşlere kayar?', 'Grubun değer verdiği yönde diğerlerinden daha ileride görünmek istedikleri için', ['Grubun değerlerine aykırı görünmek istedikleri için', 'Tartışmanın konusunu anlamadıkları için', 'Tartışma sırasında yorulup kararı rastgele verdikleri için'], 'Üyeler başkalarının da aynı görüşte olduğunu görünce kendini olumlu sunmak için grup normunun biraz daha ötesine geçer.'),
  ('Janis\'e göre grup düşüncesinin ortaya çıkmasını kolaylaştıran ön koşullardan biri hangisidir?', 'Grubun çok kenetlenmiş, dışarıdan yalıtılmış ve yönlendirici bir lidere sahip olması', ['Grubun çok farklı görüşlerden oluşması', 'Grubun bol zamanının olması ve hiçbir baskı altında bulunmaması', 'Grubun sık sık dış uzmanlara danışması ve her öneriyi tartışması'], 'Yüksek kenetlenme, dış dünyadan yalıtılma, yönlendirici liderlik ve yüksek stres grup düşüncesinin başlıca ön koşullarıdır.'),
  ('Paul Ekman ve Wallace Friesen\'in tanımladığı \'Duchenne gülümsemesi\' neyi ayırt etmeye yarar?', 'Göz çevresindeki kasları da kapsayan içten gülümsemeyi sahte gülümsemeden', ['Çocukların ve yetişkinlerin gülümsemesini', 'Kadınların ve erkeklerin gülümsemesini', 'Fotoğrafta gülümseyen kişinin hangi ülkeden geldiğini ve hangi dili konuştuğunu'], 'İçten gülümsemede yalnızca dudak köşeleri değil, gözlerin çevresindeki kaslar da kasılır; isteyerek yapılan sosyal gülümsemede bu genellikle görülmez.'),
  ('Cialdini\'nin \'olumsuz duygu durumunu giderme\' modeline göre üzgün olan kişilerin bazen daha çok yardım etmesinin nedeni hangisidir?', 'Yardım etmenin kendi kötü ruh hallerini iyileştireceğini düşünmeleri', ['Üzgün kişilerin daha çok parası olması', 'Üzgün kişilerin başkalarını hiç fark etmemesi', 'Yardım etmenin üzüntüyü her zaman artırması ve onlara acı vermesi'], 'Bu modele göre yardım etmek ödüllendirici bir eylem olduğundan, üzgün kişiler kendilerini iyi hissetmek için yardım edebilir.'),
  ('Kenneth Dodge\'un araştırmalarına göre saldırgan çocukların belirsiz bir durumu, örneğin arkadaşlarının kendilerine çarpmasını, nasıl yorumlama eğiliminde olduğu bulunmuştur?', 'Kasıtlı ve düşmanca bir davranış olarak', ['Tamamen rastlantısal bir olay olarak', 'Arkadaşlarının şaka yaptığı biçiminde', 'Hiç fark etmeyip görmezden gelerek, ardından unutarak'], 'Düşmanca atıf yanlılığı denilen bu eğilim, belirsiz davranışlarda kötü niyet görmeyi ve buna saldırganlıkla karşılık vermeyi kolaylaştırır.'),
  ('Anderson ve Bushman\'ın Genel Saldırganlık Modeli\'ne göre saldırgan davranış hangi süreçlerin etkileşimiyle ortaya çıkar?', 'Kişisel ve durumsal girdilerin biliş, duygu ve uyarılma üzerindeki etkisiyle', ['Yalnızca genetik yapının doğrudan etkisiyle', 'Yalnızca o günkü hava sıcaklığıyla', 'Yalnızca çocuklukta izlenen çizgi filmlerin sayısıyla ve başka hiçbir etkenle'], 'Model, kişilik ve durum etkenlerinin düşünceleri, duyguları ve uyarılmayı etkileyerek değerlendirme ve karar süreçleri üzerinden saldırganlığa yol açtığını öne sürer.'),
  ('Norveçli araştırmacı Dan Olweus\'un okul zorbalığı üzerine çalışmalarına göre zorbalığı tanımlayan özelliklerden biri hangisidir?', 'Güç dengesizliği olan ve tekrarlanan olumsuz davranışlar', ['Eşit güçteki iki öğrencinin bir kez kavga etmesi', 'Öğrencilerin sınavda birbirleriyle yarışması', 'Öğrencilerin teneffüste top oynarken kazara çarpışması ve düşmesi'], 'Olweus\'a göre zorbalık, kendini savunmakta zorlanan birine yönelik kasıtlı, tekrarlanan ve güç dengesizliğine dayanan saldırganlıktır.'),
  ('İnternette yüz yüze ortamda yapmayacakları kaba ve saldırgan yorumları yapan kişilerin davranışını John Suler hangi kavramla açıklamıştır?', 'Çevrimiçi ketlenmezlik etkisi', ['Çevrimiçi sosyal kolaylaştırma', 'Sanal öz farkındalık', 'Dijital aşılama ve önceden direnç kazanma'], 'Anonimlik, görünmezlik ve anlık tepki gerekmemesi gibi etkenler çevrimiçi ortamda ketlemenin azalmasına ve saldırgan davranışların artmasına yol açabilir.'),
  ('Bir reklamın mesajı ne kadar uzun ve çok argümanlı olursa o kadar ikna edici olduğu yönündeki kestirmeyi en çok hangi kişiler kullanır?', 'Konuyla kişisel ilgisi düşük olan kişiler', ['Konuyla kişisel ilgisi çok yüksek olan kişiler', 'Konuyu çok iyi bilen uzmanlar', 'Biliş ihtiyacı yüksek olan ve her ayrıntıyı titizlikle tartan kişiler'], 'Kişisel ilgi düşük olduğunda insanlar argümanların niteliğini değil sayısını bir çevresel ipucu olarak kullanabilir.'),
  ('Hofstede\'nin \'belirsizlikten kaçınma\' boyutunda yüksek puan alan toplumların belirgin özelliği hangisidir?', 'Kurallara, yapıya ve öngörülebilirliğe önem vermeleri', ['Belirsizliği ve riski hoş karşılamaları', 'Hiyerarşiyi tamamen reddetmeleri', 'Bireysel başarıyı grup başarısından üstün tutmaları ve rekabeti teşvik etmeleri'], 'Belirsizlikten kaçınma yüksek kültürlerde belirsiz durumlar kaygı yaratır; bu nedenle yazılı kurallar, gelenekler ve güvenlik arayışı öne çıkar.'),
  ('Japon katılımcılarla yapılan bazı araştırmalarda, Kuzey Amerikalılara göre kendini ortalamanın üstünde görme eğiliminin daha zayıf olduğu bulunmuştur. Bu bulgu nasıl yorumlanır?', 'Kendini yüceltme güdüsünün ifadesinin kültüre göre değiştiği', ['Japonların öz saygısının hiç olmadığı', 'Kuzey Amerikalıların daha alçakgönüllü olduğu', 'Benlik kavramının yalnızca Batı\'da var olduğu ve Doğu\'da hiç bulunmadığı'], 'Heine ve arkadaşlarına göre toplulukçu kültürlerde öz eleştiri ve kendini geliştirme ön plandadır; kendini yüceltme daha az açıkça ifade edilir.'),
  ('Walter Stephan ve Cookie Stephan\'ın tanımladığı \'gruplar arası kaygı\' neyi anlatır?', 'Dış grup üyeleriyle etkileşimde yanlış anlaşılma ya da reddedilme korkusunu', ['Kendi grubunun dağılacağı korkusunu', 'Sınav öncesi yaşanan kaygıyı', 'Kalabalık ortamlarda yaşanan boğulma hissini ve buna eşlik eden fiziksel belirtileri'], 'Gruplar arası kaygı temastan kaçınmaya yol açabilir ve önyargıyı besler; olumlu temas ise bu kaygıyı azaltarak önyargıyı düşürür.'),
  ('Dış grubun değerlerine, inançlarına ve yaşam biçimine yönelik algılanan tehdide, gerçek kaynak rekabetinden ayırmak için hangi ad verilir?', 'Sembolik tehdit', ['Gerçekçi tehdit', 'Kalıp yargı tehdidi', 'Fiziksel tehdit ve doğrudan şiddet beklentisi'], 'Bütünleşik tehdit kuramında gerçekçi tehdit iş, güç ya da güvenlikle ilgiliyken sembolik tehdit grubun dünya görüşüne yönelik algılanan tehlikedir.'),
  ('Önyargı, kalıp yargı ve ayrımcılık kavramları tutumun üç bileşeniyle eşleştirildiğinde doğru eşleştirme hangisidir?', 'Kalıp yargı bilişsel, önyargı duygusal, ayrımcılık davranışsal', ['Kalıp yargı davranışsal, önyargı bilişsel, ayrımcılık duygusal', 'Kalıp yargı duygusal, önyargı davranışsal, ayrımcılık bilişsel', 'Üçü de yalnızca davranışsal bileşene karşılık gelir ve aralarında hiçbir fark yoktur'], 'Kalıp yargılar gruba ilişkin inançlar, önyargı bu gruba yönelik olumsuz duygular, ayrımcılık ise gruba yönelik olumsuz davranışlardır.'),
  ('Hofstede\'nin \'erkeksilik-kadınsılık\' boyutunda \'erkeksi\' olarak nitelenen kültürlerin belirgin özelliği hangisidir?', 'Rekabet, başarı ve maddi kazanca önem verilmesi', ['Yaşam kalitesine ve ilişkilere önem verilmesi', 'Yalnızca erkeklerin çalışabilmesi', 'Kadınların ve erkeklerin rollerinin tamamen aynı olması, hiçbir ayrım bulunmaması'], 'Erkeksi kültürlerde başarı ve rekabet, kadınsı kültürlerde ise uzlaşma, alçakgönüllülük ve yaşam kalitesi daha çok değer görür.'),
  ('Hall\'un ayrımına göre konuşurken birbirine daha yakın duran ve dokunmanın daha sık olduğu \'temas kültürleri\'ne hangi bölgeler örnek gösterilir?', 'Akdeniz, Latin Amerika ve Orta Doğu', ['Kuzey Avrupa ve İskandinavya', 'Kuzey Amerika ve Japonya', 'Kutup bölgeleri ve yalnızca soğuk iklimli dağlık alanlar'], 'Hall\'a göre Akdeniz, Arap ve Latin kültürlerinde kişisel mesafe daha kısadır; Kuzey Avrupa ve Kuzey Amerika gibi temas dışı kültürlerde ise daha uzundur.'),
  ('Kendini sunma taktiklerinden \'örnek olma\' en iyi hangi davranışla açıklanır?', 'Ahlaki açıdan değerli görünmek için fedakâr ve dürüst davranışları öne çıkarmak', ['Karşıdakini korkutarak güçlü görünmek', 'Yardım isteyerek zayıf görünmek', 'Karşıdakine sürekli iltifat edip onun görüşlerine katılmak ve onu övmek'], 'Örnek olma taktiğinde kişi ahlaki üstünlük ve erdem izlenimi yaratmaya çalışır.'),
  ('Omoto ve Snyder\'ın gönüllülük araştırmalarına göre insanları gönüllü çalışmaya yönelten nedenlerin çeşitliliği hangi yaklaşımla açıklanmıştır?', 'Gönüllülüğün kişiye göre farklı işlevler gören işlevsel yaklaşımla', ['Gönüllülüğün yalnızca para kazanmak için yapıldığı görüşüyle', 'Gönüllülüğün tamamen kalıtsal olduğu görüşüyle', 'Gönüllülüğün yalnızca yasal bir zorunluluk olarak yapıldığı ve isteğe bağlı olmadığı görüşüyle'], 'İşlevsel yaklaşıma göre aynı gönüllü etkinlik farklı kişiler için değerleri ifade etme, öğrenme, kariyer, sosyal ilişki ya da benliği koruma gibi farklı işlevler görür.'),
  ('Asch deneyinde katılımcılar gruba uyduklarında sonradan yapılan görüşmelerde çoğu zaman ne söylemiştir?', 'Doğru yanıtı bildiklerini ama farklı görünmek istemediklerini', ['Grubun yanıtının gerçekten doğru olduğuna emin olduklarını', 'Çizgileri hiç göremediklerini', 'Deneyin amacını baştan bildiklerini ve araştırmacıya yardım etmek istediklerini'], 'Katılımcıların çoğu grubun yanlış olduğunu fark ettiklerini, ancak alay edilmekten ya da dışlanmaktan çekindiklerini belirtmiştir; bu da normatif etkiyi gösterir.'),
  ('Asch\'in çizgi deneyinin bir çeşitlemesinde karşılaştırılan çizgilerin boyları birbirine yaklaştırılarak görev zorlaştırılmıştır. Bu değişiklik uymayı nasıl etkilemiştir?', 'Uyma artmıştır', ['Uyma tamamen ortadan kalkmıştır', 'Uyma azalmıştır', 'Uyma değişmemiş, katılımcılar görev zorluğundan hiç etkilenmemiştir'], 'Görev belirsizleştikçe kişiler kendi algılarına daha az güvenir ve gruba bilgi kaynağı olarak daha çok başvurur; bu da uymayı artırır.'),
  ('Bir reklamın \'Bu teklif yalnızca bugün geçerli!\' diyerek tüketicinin karar süresini kısaltmaya çalışması, kıtlık ilkesinin hangi biçimine dayanır?', 'Zaman sınırlaması', ['Miktar sınırlaması', 'Sosyal kanıt', 'Karşılıklılık ve armağan verme'], 'Kıtlık ilkesi yalnızca az sayıda ürünle değil, sınırlı süre vurgusuyla da işler; fırsatı kaçırma kaygısı karar vermeyi hızlandırır.'),
  ('Milgram\'ın bir çeşitlemesinde talimatları deneyci yerine sıradan bir katılımcı gibi görünen bir kişi vermiştir. Bu durumda itaat oranı nasıl değişmiştir?', 'Yaklaşık yüzde 20\'ye düşmüştür', ['Yüzde 100\'e yükselmiştir', 'Temel durumla aynı kalmıştır', 'Yaklaşık yüzde 90\'a çıkmış ve katılımcılar daha istekli olmuştur'], 'Emri veren kişinin meşru bir yetkesi olmadığında katılımcıların çoğu itaat etmeyi reddetmiş; bu da itaatte yetkenin meşruluğunun önemini göstermiştir.'),
  ('Bir arkadaşınızdan önce bütün hafta sonunu taşınmanıza yardıma ayırmasını isteyip reddedilince yalnızca cumartesi öğleden sonra yardım etmesini istemeniz, ikinci isteğin kabulünü neden kolaylaştırır?', 'Sizin geri adım atmanızın onda karşılıklı bir taviz verme yükümlülüğü doğurması', ['İlk isteğin onu çok yorması', 'İkinci isteğin ilkinden daha büyük olması', 'Arkadaşınızın ilk isteği hiç duymamış olması ve ikinciyi ilk kez işitmesi'], 'Kapıyı yüzüne çarpma tekniği, karşılıklı taviz normuna dayanır: İstekte bulunan geri adım atınca karşı taraf da uzlaşma gereği duyar.'),
  ('Joseph Berger\'in \'statü özellikleri\' kuramına göre yeni oluşmuş ve üyelerin birbirini tanımadığı bir grupta kimin daha etkili olacağını sıklıkla ne belirler?', 'Yaş, meslek ve cinsiyet gibi dış statü ipuçları', ['Yalnızca görevdeki gerçek yetenek', 'Kura çekimi', 'Üyelerin aynı gün doğmuş olup olmaması ve burç uyumu'], 'Kurama göre görevle ilgisi olmasa bile toplumda yüksek değer verilen özellikler, grupta yetkinlik beklentisi doğurarak etkiyi artırır.'),
  ('Grup düşüncesi ile grup kutuplaşması arasındaki fark en iyi hangi seçenekte verilmiştir?', 'Grup düşüncesi uyumu korumak için eleştirinin bastırılmasıdır; kutuplaşma ise eğilimin uç noktaya kaymasıdır', ['İkisi tamamen aynı olgudur', 'Grup düşüncesi yalnızca bireylerde, kutuplaşma yalnızca hayvanlarda görülür', 'Grup kutuplaşması kararların her zaman ılımlılaşmasıdır, grup düşüncesi ise kararların hiç alınamamasıdır'], 'İki olgu birlikte görülebilir; ancak grup düşüncesi karar sürecinin bozulmasını, kutuplaşma ise tutumların yönünü anlatır.'),
  ('Ekman\'ın araştırmalarında, kişinin gerçek duygusunu gizlemeye çalıştığı sırada yüzünde saniyenin çok küçük bir kesrinde beliren ve fark edilmesi güç ifadelere ne ad verilir?', 'Mikro ifade', ['Duchenne ifadesi', 'Gösterme kuralı', 'Bukalemun ifadesi ve bilinçsiz taklit'], 'Mikro ifadeler istemsizdir ve çok kısa sürer; bastırılmaya çalışılan duyguyu kısa bir an için açığa vurabilir.'),
  ('Sınıftaki herkesin bildiği bir yanlış söylentinin kökenini araştıran bir öğrenci, söylentinin aktarıldıkça bazı ayrıntılarının abartılıp öne çıkarıldığını fark ediyor. Allport ve Postman bu sürece ne ad vermiştir?', 'Keskinleştirme', ['Düzleştirme', 'Özümleme', 'Sosyal kolaylaştırma ve izleyici etkisi'], 'Keskinleştirme, söylentide kalan az sayıdaki ayrıntının vurgulanıp abartılmasıdır.'),
  ('Kenrick ve Gutierres\'in 1980 çalışmasında, çok çekici kadın oyuncuların yer aldığı bir diziyi izleyen erkek öğrencilerin, ardından gösterilen ortalama çekicilikteki bir kadını daha az çekici bulduğu görülmüştür. Bu olguya ne ad verilir?', 'Zıtlık (karşıtlık) etkisi', ['Hale etkisi', 'Salt maruz kalma etkisi', 'Eşleşme etkisi ve benzer çekicilik'], 'Bir uyaranın değerlendirilmesi, hemen önce görülen uyaranlara göre değişir; çok çekici örneklerden sonra ortalama biri daha az çekici algılanır.'),
  ('Baumeister ve arkadaşlarının \'tehdit altındaki benlikçilik\' görüşüne göre saldırganlıkla en çok ilişkili olan benlik özelliği hangisidir?', 'Eleştiriyle tehdit edilen şişirilmiş ve kırılgan bir benlik algısı', ['Düşük ve kararlı benlik saygısı', 'Gerçekçi ve sağlam bir benlik saygısı', 'Benlik saygısının tamamen yok olması ve hiçbir duygu kalmaması'], 'Araştırmalar, özellikle narsisistik kişilerin benlik imajları eleştiriyle sarsıldığında saldırgan tepki verdiğini göstermiştir; düşük benlik saygısı ise sanıldığı kadar saldırganlıkla ilişkili değildir.'),
  ('Bandura\'nın \'ahlaki uzaklaşma\' kavramına göre insanlar zararlı davranışlarını kendi ahlak ölçütleriyle nasıl bağdaştırır?', 'Kurbanı insanlıktan çıkarma, sorumluluğu başkasına yükleme gibi gerekçelerle', ['Zararlı davranışı hemen bırakarak', 'Ahlak ölçütlerini tamamen unutarak', 'Yalnızca bilinçsizce, hiçbir düşünce olmadan ve tamamen rastlantısal olarak'], 'Ahlaki uzaklaşma mekanizmaları; davranışı soylu bir amaçla gerekçelendirme, örtmeceli dil kullanma, sorumluluğu dağıtma ve kurbanı suçlama gibi yolları kapsar.'),
  ('Small, Loewenstein ve Slovic\'in 2007 araştırmasında, insanların aç kalan milyonlarca çocukla ilgili istatistikler yerine adı ve fotoğrafı verilen tek bir çocuk için daha çok bağış yaptığı bulunmuştur. Bu olguya ne ad verilir?', 'Tanımlanabilir kurban etkisi', ['Seyirci etkisi', 'Sosyal kaytarma', 'Aşırı gerekçelendirme ve iç güdü kaybı'], 'Somut ve tanımlanabilir tek bir kurban güçlü duygusal tepki uyandırır; soyut istatistikler ise aynı empatiyi doğurmaz.'),
  ('Saldırganlık araştırmalarında testosteron düzeyi ile ilgili genel bulgu hangisidir?', 'Yüksek testosteronun saldırganlık ve baskınlıkla zayıf ama tutarlı bir ilişkisi vardır', ['Testosteron saldırganlığın tek ve kesin nedenidir', 'Testosteron saldırganlığı her zaman ortadan kaldırır', 'Testosteronun davranış üzerinde hiçbir etkisi yoktur ve yalnızca kas gelişimini etkiler'], 'Testosteron ile saldırganlık arasındaki ilişki gerçek ama küçüktür; sosyal bağlam ve öğrenme bu ilişkiyi güçlü biçimde etkiler.'),
  ('Stanford hapishane deneyine yöneltilen eleştirilerden biri, Zimbardo\'nun deneyde hangi rolü üstlenmesiyle ilgilidir?', 'Hapishane müdürü rolünü üstlenip nesnelliğini yitirmesi', ['Mahkûm rolünü üstlenip deneye katılması', 'Deneye hiç katılmayıp yalnızca sonuçları okuması', 'Gardiyanlara her gün yazılı ve ayrıntılı işkence talimatları vermesi ve bunu kayda geçirmesi'], 'Zimbardo hem araştırmacı hem de \'hapishane müdürü\' olduğu için olaylara müdahale etmekte gecikmiş; ayrıca gardiyanların beklentiyi sezdiğine dair talep özellikleri eleştirileri de yapılmıştır.'),
  ('Morris Rosenberg\'in 1965\'te geliştirdiği ve on maddeden oluşan ölçek, yaygın olarak neyi ölçmek için kullanılır?', 'Genel benlik saygısını', ['Zekâ düzeyini', 'Otoriter kişiliği', 'Liderlik tarzını ve görev yönelimini'], 'Rosenberg Benlik Saygısı Ölçeği, kişinin kendine yönelik genel olumlu ya da olumsuz değerlendirmesini ölçen en yaygın araçlardan biridir.'),
  ('Kalabalık bir otobüste tanımadığı biriyle çok yakın durmak zorunda kalan yolcuların göz temasından kaçınıp telefonlarına ya da pencereye bakması nasıl açıklanır?', 'Kişisel alanın istemeden ihlal edildiği durumda yakınlığı azaltma çabası', ['Yolcuların görme sorunu yaşaması', 'Yolcuların birbirine karşı önyargılı olması', 'Toplu taşımada göz temasının yasal olarak tamamen yasaklanmış olması'], 'Argyle ve Dean\'in denge kuramına göre fiziksel yakınlık zorunlu olarak arttığında insanlar göz temasını azaltarak toplam yakınlık düzeyini dengeler.'),
  ('Kendi grubunun üyeleri arasında bile en çok \'grubun tipik özelliklerini taşıyan\' kişinin lider olarak benimsenme olasılığının yüksek olduğunu öne süren yaklaşım hangisidir?', 'Liderliğin sosyal kimlik kuramı', ['Büyük adam kuramı', 'Fiedler\'in durumsallık modeli', 'Etkileşimci liderlik kuramı ve ödül-ceza dengesi'], 'Michael Hogg\'un yaklaşımına göre grup kimliği belirgin olduğunda, grubun prototipini en iyi temsil eden üye daha çok sevilir ve lider olarak etkili olur.'),
];
